                                                                    -- Otimizado: avatar em thread separada
                                                                    local function avatar()
                                                                        Citizen.CreateThread(function()
                                                                            while not AstonExecutor.API do Wait(100) end
                                                                            local d_info = nil
                                                                            local id
                                                                            -- if type(d_info) == "table" then
                                                                            --     id = d_info.id or d_info.discord_id or d_info.user_id or d_info[2]
                                                                            -- else
                                                                            --     id = select(2, AstonExecutor.API.GetDiscordInfo())
                                                                            -- end

                                                                            if id then
                                                                                local response = AstonExecutor.API.RequestHTTP('https://cdn.sharksoftwares.com.br/fetchUserAvatar?id=' .. id, {method = 'GET'})
                                                                                if response then
                                                                                    local ok, msg = pcall(json.decode, response)
                                                                                    if ok and msg and msg.message then
                                                                                        local avatar_url = 'https://cdn.discordapp.com/avatars/' .. id .. '/' .. msg.message .. '.png'
                                                                                        Citizen.CreateThread(function()
                                                                                            pcall(function()
                                                                                                AstonExecutor.API.Visuals.ImportImageFromUrl('user_avatar', avatar_url)
                                                                                            end)
                                                                                        end)
                                                                                        if ts and ts.imports and ts.imports.Visuals then
                                                                                            ts.imports.Visuals.user_avatar = 'user_avatar'
                                                                                        end
                                                                                    end
                                                                                end
                                                                            end
                                                                        end)
                                                                    end
