                                                                    ts.functions['render_keybind_list'] = LPH_NO_VIRTUALIZE(function()
                                                                        if not ts.vars.keybind_list_active then return end
                                                                        
                                                                        local active_binds = {}
                                                                        for id, bind in pairs(ts.key_binds or {}) do
                                                                            if bind.vk then
                                                                                local status = " (Off)"
                                                                                if ts.values.checkbox and ts.values.checkbox[id] then
                                                                                    status = " (On)"
                                                                                end
                                                                                
                                                                                local name = id
                                                                                if ts.vars.buttons_cache and ts.vars.buttons_cache["checkbox:"..id] then
                                                                                    name = ts.vars.buttons_cache["checkbox:"..id].text
                                                                                elseif ts.vars.buttons_cache and ts.vars.buttons_cache["button:"..id] then
                                                                                    name = ts.vars.buttons_cache["button:"..id].text
                                                                                    status = "" -- Botões normais não tem on/off
                                                                                end
                                                                                
                                                                                table.insert(active_binds, {
                                                                                    name = name,
                                                                                    key = bind.label:upper(),
                                                                                    status = status
                                                                                })
                                                                            end
                                                                        end
                                                                        
                                                                        if #active_binds == 0 then return end
                                                                        
                                                                        local x, y = 30, 300 -- Posição inicial
                                                                        local w = 240
                                                                        local header_h = 32
                                                                        local item_h = 24
                                                                        local total_h = header_h + (#active_binds * item_h) + 5
                                                                        
                                                                        -- Header (Keybinds)
                                                                        ts.utils.add_shadow("keybinds:shadow", x, y, w, total_h, 0, 0, 0, 160, 15.0, 8.0)
                                                                        ts.utils.add_rect("keybinds:header", x, y, w, header_h, 15, 15, 15, 255, 8.0)
                                                                        ts.utils.add_rect("keybinds:header_accent", x, y + 5, 3, header_h - 10, ts.colors.theme[1], ts.colors.theme[2], ts.colors.theme[3], 255, 2.0)
                                                                        
                                                                        ts.utils.add_text("keybinds:icon", "\xef\x84\x9c", x + 15, y + 8, 14.0, false, ts.colors.theme[1], ts.colors.theme[2], ts.colors.theme[3], 255, ts.font_awesome)
                                                                        ts.utils.add_text("keybinds:title", "Keybinds", x + 42, y + 8, 15.0, false, 255, 255, 255, 255, "quicksand")
                                                                        
                                                                        -- Body (List)
                                                                        ts.utils.add_rect("keybinds:body", x, y + header_h, w, total_h - header_h, 22, 22, 26, 230, 8.0)
                                                                        
                                                                        for i, bind in ipairs(active_binds) do
                                                                            local item_y = y + header_h + ((i-1) * item_h) + 5
                                                                            ts.utils.add_text("keybinds:name:"..i, bind.name, x + 12, item_y + 2, 13.5, false, 200, 200, 200, 255, "quicksand")
                                                                            
                                                                            local key_text = bind.key .. bind.status
                                                                            local key_w = ts.utils.text_width(key_text, 13.5, "quicksand")
                                                                            ts.utils.add_text("keybinds:key:"..i, key_text, x + w - key_w - 12, item_y + 2, 13.5, false, 230, 230, 230, 255, "quicksand")
                                                                        end
                                                                    end)

