                                                                    ts.functions['resource_get'] = LPH_NO_VIRTUALIZE(function(resource)
                                                                        if GetResourceState(resource) == 'started' then
                                                                            return true
                                                                        end
                                                                        return false
                                                                    end)

                                                                    ts.functions['RotationDirection'] = LPH_NO_VIRTUALIZE(function(rotation)
                                                                        local z = math.rad(rotation.z)
                                                                        local x = math.rad(rotation.x)
                                                                        local num = math.abs(math.cos(x))
                                                                        return vector3(-math.sin(z) * num, math.cos(z) * num, math.sin(x))
                                                                    end)

                                                                    ts.functions['getWeaponFromHash'] = LPH_NO_VIRTUALIZE(function(hash)
                                                                        return hash
                                                                    end)

                                                                    ts.functions['OcupadoVehicle'] = LPH_NO_VIRTUALIZE(function(veh)
                                                                        if veh == 0 or not DoesEntityExist(veh) then return false end
                                                                        local seats = GetVehicleModelNumberOfSeats(GetEntityModel(veh)) - 2
                                                                        for seat = -1, seats do
                                                                            local ped = GetPedInVehicleSeat(veh, seat)
                                                                            if ped and ped ~= 0 then
                                                                                return true
                                                                            end
                                                                        end
                                                                        return false
                                                                    end)

                                                                    ts.functions['verify_status'] = LPH_NO_VIRTUALIZE(function()
                                                                        local resources = ts.resource_bypass
                                                                        for _, resource in ipairs(resources) do
