                                                                                local loadeds = {};
                                                                                for _, loaded in ipairs(loadeds) do
                                                                                    if loaded == resource then
                                                                                        return true
                                                                                    else
                                                                                    return false 
                                                                                    end
                                                                                end
                                                                            end
                                                                        end
                                                                    end)
