                                                                    ts.functions['rot_to_dir'] = LPH_NO_VIRTUALIZE(function(rotation)
                                                                        local z = math.rad(rotation.z)  
                                                                        local x = math.rad(rotation.x)
                                                                        local num = math.abs(math.cos(x))
                                                                        
                                                                        return vector3(
                                                                        -math.sin(z) * num,
                                                                        math.cos(z) * num,
                                                                        math.sin(x)
                                                                        )
                                                                    end)

