                                                                    ts.functions['getCooldown'] = LPH_NO_VIRTUALIZE(function(type)
                                                                        local last = AstonExecutor.API.GetVar("last_gen_" .. type)
                                                                        last = tonumber(last)
                                                                        if not last then return 0 end
                                                                        local now = os.time()
                                                                        local diff = now - last
                                                                        if diff < 3600 then
                                                                            return 3600 - diff
                                                                        end
                                                                        return 0
                                                                    end)

