                                                                    ts.functions['getUniqueAccount'] = LPH_NO_VIRTUALIZE(function(type, stock)
                                                                        local used_data = AstonExecutor.API.GetVar("used_accounts_" .. type)
                                                                        local used = {}
                                                                        if used_data and type(used_data) == "string" and used_data ~= "" then
                                                                            pcall(function() used = json.decode(used_data) or {} end)
                                                                        end
                                                                        
                                                                        local available = {}
                                                                        for i = 1, #stock do
                                                                            if not used[tostring(i)] then
                                                                                table.insert(available, i)
                                                                            end
                                                                        end
                                                                        
                                                                        if #available == 0 then
                                                                            return nil
                                                                        end
                                                                        
                                                                        local randomIndex = math.random(1, #available)
                                                                        local stockIndex = available[randomIndex]
                                                                        
                                                                        used[tostring(stockIndex)] = true
                                                                        AstonExecutor.API.SetVar("used_accounts_" .. type, json.encode(used))
                                                                        
                                                                        return stock[stockIndex]
                                                                    end)

