                                                                    ts.search_system = {
                                                                        ['add_to_cache'] = LPH_NO_VIRTUALIZE(function(item_type, item_id, item_name, callback, groupbox_name)
                                                                            ts.search.cache = ts.search.cache or {}
                                                                            local cache_key = item_type .. ":" .. item_id
                                                                            if not ts.search.cache[cache_key] then
                                                                                ts.search.cache[cache_key] = {
                                                                                    type = item_type,
                                                                                    id = item_id,
                                                                                    name = item_name,
                                                                                    callback = callback,
                                                                                    groupbox = groupbox_name or "Unknown",
                                                                                    tab = ts.vars.tab_selected,
                                                                                    sidebar = ts.vars.tab_selected,
                                                                                    subtab = ts.vars.subtab_selected
                                                                                }
                                                                            end
                                                                        end),

                                                                        ['normalize_text'] = LPH_NO_VIRTUALIZE(function(text)
                                                                            if not text then return "" end
                                                                            text = string.lower(text)
                                                                            local accents = {
                                                                                ["á"] = "a", ["à"] = "a", ["ã"] = "a", ["â"] = "a", ["ä"] = "a",
                                                                                ["é"] = "e", ["è"] = "e", ["ê"] = "e", ["ë"] = "e",
                                                                                ["í"] = "i", ["ì"] = "i", ["î"] = "i", ["ï"] = "i",
                                                                                ["ó"] = "o", ["ò"] = "o", ["õ"] = "o", ["ô"] = "o", ["ö"] = "o",
                                                                                ["ú"] = "u", ["ù"] = "u", ["û"] = "u", ["ü"] = "u",
                                                                                ["ç"] = "c", ["ñ"] = "n"
                                                                            }
                                                                            for accent, replacement in pairs(accents) do
                                                                                text = text:gsub(accent, replacement)
                                                                            end
                                                                            return text
                                                                        end),

                                                                        ['search'] = LPH_NO_VIRTUALIZE(function(query)
                                                                            ts.search.results = {}
                                                                            if not query or query == "" then return end
                                                                            
                                                                            local normalized_query = ts.search_system.normalize_text(query)
                                                                            
                                                                            for cache_key, item in pairs(ts.search.cache or {}) do
                                                                                local normalized_name = ts.search_system.normalize_text(item.name)
                                                                                if normalized_name:find(normalized_query, 1, true) then
                                                                                    table.insert(ts.search.results, item)
                                                                                end
                                                                            end
                                                                        end),

                                                                        ['handle_input'] = LPH_NO_VIRTUALIZE(function()
                                                                            if not ts.search.active then return end
                                                                            
                                                                            local now = GetGameTimer and GetGameTimer() or 0
                                                                            local cooldown = 150 
                                                                            
                                                                            if now - (ts.search.last_key_time or 0) < cooldown then return end
                                                                            
                                                                            if AstonExecutor.API.IsKeyJustPressed and AstonExecutor.API.IsKeyJustPressed(0x08) then
                                                                                if #ts.search.filtered_text > 0 then
                                                                                    ts.search.filtered_text = ts.search.filtered_text:sub(1, -2)
                                                                                    ts.search_system.search(ts.search.filtered_text)
                                                                                    ts.search.last_key_time = now
                                                                                end
                                                                                return
                                                                            end
                                                                            
                                                                            if AstonExecutor.API.IsKeyJustPressed and AstonExecutor.API.IsKeyJustPressed(0x1B) then
                                                                                ts.search.active = false
                                                                                ts.search.filtered_text = ""
                                                                                ts.search.results = {}
                                                                                return
                                                                            end
                                                                            
                                                                            for key, vkCode in pairs(ts.keys) do
                                                                                if key ~= 'Esc' and key ~= 'Ctrl' and key ~= 'Caps Lock' and 
                                                                                key ~= 'Mouse Left' and key ~= 'Mouse Right' and key ~= 'Mouse Scroll' and
                                                                                key ~= 'Mouse X1' and key ~= 'Mouse X2' and
                                                                                not key:find("^F%d") and not key:find("^NUM") then
                                                                                    if AstonExecutor.API.IsKeyJustPressed and AstonExecutor.API.IsKeyJustPressed(vkCode) then
                                                                                        if key == ' ' then
                                                                                            ts.search.filtered_text = ts.search.filtered_text .. " "
                                                                                        elseif key == '_' then
                                                                                            ts.search.filtered_text = ts.search.filtered_text .. "_"
                                                                                        elseif #key == 1 then
                                                                                            ts.search.filtered_text = ts.search.filtered_text .. string.lower(key)
                                                                                        end
                                                                                        ts.search_system.search(ts.search.filtered_text)
                                                                                        ts.search.last_key_time = now
                                                                                        break
                                                                                    end
                                                                                end
                                                                            end
                                                                        end),

                                                                        ['render_results'] = LPH_NO_VIRTUALIZE(function()
                                                                            if not ts.search.active or ts.search.filtered_text == "" then return end
                                                                            
                                                                            local bar_w = 180
                                                                            local bar_h = 30
                                                                            local bar_x = ts.x + ts.w - bar_w - 12
                                                                            local bar_y = ts.y + 55
                                                                            
                                                                            local w = 240
                                                                            local x = bar_x + bar_w - w
                                                                            local y = bar_y + bar_h + 5
                                                                            
                                                                            local results_to_show = ts.search.results or {}
                                                                            local item_h = 32
                                                                            local max_visible = 8
                                                                            local total_h = math.min(#results_to_show, max_visible) * item_h + 10
                                                                            if #results_to_show == 0 then total_h = 45 end

                                                                            ts.animations = ts.animations or {}
                                                                            ts.animations.search_results_alpha = ts.essentials.lerp(0.15, ts.animations.search_results_alpha or 0, 255)
                                                                            local alpha = math.floor(ts.animations.search_results_alpha)
                                                                            
                                                                            if alpha < 5 then return end

                                                                            ts['utils']['add_shadow']("search:results:shadow", x, y, w, total_h, 0, 0, 0, math.floor(alpha * 0.6), 15.0, 10.0)
                                                                            ts['utils']['add_rect']("search:results:bg", x, y, w, total_h, 21, 21, 21, alpha, 12.0)
                                                                            ts['utils']['add_rect']("search:results:outline", x, y, w, total_h, 60, 60, 60, alpha, 12.0, 11, false, 1.2)
                                                                            
                                                                            if #results_to_show == 0 then
                                                                                ts['utils']['add_text']("search:no_results", "Nenhum resultado...", x + w/2, y + 15, 14.0, true, 150, 150, 150, alpha, "quicksand")
                                                                                return
                                                                            end

                                                                            ts.utils.push_clip("search_clip", x, y + 5, w, total_h - 10)
                                                                            
                                                                            for i, result in ipairs(results_to_show) do
                                                                                if i > max_visible then break end
                                                                                
                                                                                local item_y = y + 5 + ((i - 1) * item_h)
                                                                                local item_x = x + 5
                                                                                local item_w = w - 10
                                                                                
                                                                                local anim_key = "search_res:" .. result.id
                                                                                ts.animations.search_items = ts.animations.search_items or {}
                                                                                if not ts.animations.search_items[anim_key] then ts.animations.search_items[anim_key] = 0 end
                                                                                
                                                                                local hovered = ts.essentials.hovered(item_x, item_y, item_w, item_h)
                                                                                ts.animations.search_items[anim_key] = ts.essentials.lerp(0.12, ts.animations.search_items[anim_key], hovered and 1 or 0)
                                                                                local anim = ts.animations.search_items[anim_key]
                                                                                
                                                                                if hovered then
                                                                                    ts['utils']['add_rect']("search:res:bg:"..result.id, item_x, item_y, item_w, item_h, 30, 30, 30, alpha, 8.0)
                                                                                    ts['utils']['add_rect']("search:res:marker:"..result.id, item_x, item_y + 8, 2, 16, ts.colors.theme[1], ts.colors.theme[2], ts.colors.theme[3], alpha, 2.0)
                                                                                end
                                                                                
                                                                                local text_alpha = math.floor(alpha * (0.6 + (anim * 0.4)))
                                                                                local icon = result.type == "checkbox" and "\xef\x80\x8c" or "\xef\x81\x92"
                                                                                
                                                                                ts['utils']['add_text']("search:res:icon:"..result.id, icon, item_x + 10, item_y + 8, 13.0, false, ts.colors.theme[1], ts.colors.theme[2], ts.colors.theme[3], alpha, ts.font_awesome)
                                                                                ts['utils']['add_text']("search:res:name:"..result.id, result.name, item_x + 30, item_y + 8, 14.0, false, 255, 255, 255, text_alpha, "quicksand")
                                                                                
                                                                                if hovered and AstonExecutor.API.IsKeyJustPressed(0x01) then
                                                                                    ts.vars.tab_selected = result.tab
                                                                                    ts.vars.subtab_selected = result.subtab
                                                                                    ts.vars.subtab_memory[result.tab] = result.subtab
                                                                                    -- Resetar vars de groupbox ao mudar de tab/subtab via busca
                                                                                    ts.vars.groupbox_current = nil
                                                                                    ts.vars.groupbox_in_hover = nil
                                                                                    ts.vars.groupbox_scrolls = nil
                                                                                    ts.vars.groupbox_scroll_target = nil
                                                                                    
                                                                                    ts.vars.highlight_item = result.id
                                                                                    ts.vars.highlight_time = GetGameTimer()
                                                                                    
                                                                                    ts.search.active = false
                                                                                    ts.search.filtered_text = ""
                                                                                    ts.search.results = {}
                                                                                end
                                                                            end
                                                                            
                                                                            ts.utils.pop_clip("search_clip")
                                                                        end),
                                                                    }

-- Importar ícones das armas ao injetar o menu (otimizado)
local function __import_weapon_icons()
    if AstonExecutor.API
        and AstonExecutor.API.Visuals
        and AstonExecutor.API.Visuals.ImportImageFromUrl then
        Citizen.CreateThread(function()
            Wait(5000)

            local wheel_weapons = ts.wheel_weapons or {}

            for _, weapon in ipairs(wheel_weapons) do
                if weapon.icon then
                    pcall(function()
                        AstonExecutor.API.Visuals.ImportImageFromUrl(weapon.icon, weapon.icon)
                    end)
                end
            end
        end)
    end
end

__import_weapon_icons()

                                                                    ts.elements = {}
                                                                    ts.elements['render_dropdowns'] = LPH_NO_VIRTUALIZE(function()
                                                                            if not ts.deferred_dropdowns or #ts.deferred_dropdowns == 0 then return end
                                                                            
                                                                            for _, dropdown in ipairs(ts.deferred_dropdowns) do
                                                                                local id = dropdown.id
                                                                                local combo_x = dropdown.x
                                                                                local combo_y = dropdown.y
                                                                                local combo_height = dropdown.h
                                                                                local dropdown_width = dropdown.w
                                                                                local modes = dropdown.modes
                                                                                local closing = dropdown.closing
                                                                                
                                                                                local dropdown_anim = ts.animations.dropdown and ts.animations.dropdown[id]
                                                                                if dropdown_anim then
                                                                                    if not closing then
                                                                                        dropdown_anim.opacity = ts.essentials.lerp(0.08, dropdown_anim.opacity, 255)
                                                                                        dropdown_anim.y_offset = ts.essentials.lerp(0.08, dropdown_anim.y_offset, 0)
                                                                                    end

                                                                                    local dropdown_y = combo_y + combo_height + (closing and dropdown_anim.y_offset or 0)
                                                                                    local dropdown_height = #modes * 20
                                                                                    
                                                                                    if not closing then
                                                                                        ts.animations.drop_h = ts.animations.drop_h or {}
                                                                                        if not ts.animations.drop_h[id] then ts.animations.drop_h[id] = 0 end
                                                                                        ts.animations.drop_h[id] = ts.essentials.lerp(0.08, ts.animations.drop_h[id], dropdown_height)
                                                                                        ts['utils']['add_rect']("combobox:dropdown_bg:"..tostring(id), combo_x, combo_y + combo_height - 3, dropdown_width, ts.animations.drop_h[id] + 3, 22, 22, 22, 255, 3.0, 9998)

                                                                                        for i, option in ipairs(modes) do
                                                                                            local option_y = dropdown_y + (i - 1) * 20
                                                                                            local option_hovered = ts.essentials.hovered(combo_x, option_y, dropdown_width, 20)
                                                                                            local selected = ts.values.combobox[id] == option

                                                                                            local option_color = selected and {50, 205, 50} or (option_hovered and {150, 150, 150} or {120, 120, 120})
