                                                                                                ts.utils.add_text("updates_panel:feature:"..i.."_"..fi, feature, draw_ux + 38, fy, 11.5, false, 220, 220, 230, u_alpha, "quicksand")
                                                                                            end
                                                                                        end
                                                                                        current_y = current_y + item_h + 15
                                                                                    else
                                                                                        -- Atualização normal (também maior)
                                                                                        local item_h = 75
                                                                                        if current_y + item_h > updates_y - 50 and current_y < updates_y + updates_h + 50 then
                                                                                            ts.utils.add_rect("updates_panel:item"..i.."_bg", draw_ux + 20, current_y, uw - 40, item_h, 15, 15, 19, math.floor(u_alpha * 0.65), 10.0)
                                                                                            ts.utils.add_text("updates_panel:item"..i.."_title", update.title, draw_ux + 32, current_y + 17, 14.0, false, ts.colors.theme[1], ts.colors.theme[2], ts.colors.theme[3], u_alpha, "quicksand_bold")
                                                                                            ts.utils.add_text("updates_panel:item"..i.."_desc", update.desc, draw_ux + 32, current_y + 38, 11.5, false, 200, 200, 210, u_alpha, "quicksand")
                                                                                            ts.utils.add_text("updates_panel:item"..i.."_date", update.date, draw_ux + uw - 52, current_y + 17, 11.5, false, 140, 140, 150, u_alpha, "quicksand")
                                                                                        end
                                                                                        current_y = current_y + item_h + 15
                                                                                    end
                                                                                end
                                                                                
                                                                                ts.utils.pop_clip("updates_clip")
                                                                                
                                                                                -- Botão Fechar
                                                                                if ts.essentials.hovered(draw_ux + uw - 35, uy + 15, 20, 20) then
                                                                                    ts.utils.add_text("updates_panel:close", "\xef\x80\x8d", draw_ux + uw - 30, uy + 17, 15.0, true, 255, 50, 50, u_alpha, ts.font_awesome)
                                                                                    if AstonExecutor.API.IsKeyJustPressed(0x01) then ts.vars.show_updates_panel = false end
                                                                                else
                                                                                    ts.utils.add_text("updates_panel:close", "\xef\x80\x8d", draw_ux + uw - 30, uy + 17, 15.0, true, 160, 160, 170, u_alpha, ts.font_awesome)
                                                                                end
                                                                            else
                                                                                ts.animations.updates_panel = 0
                                                                            end

                                                                            -- Footer de Informações do Usuário (Centralizado na Sidebar)
                                                                            local footer_h = 60
                                                                            local footer_x = x + 10
                                                                            local footer_w = 200
                                                                            local footer_y = y + h - footer_h - 15
                                                                            
                                                                            -- Background do Rodapé (Apenas se o menu não estiver colapsado horizontalmente)
                                                                            ts.utils.add_rect("sidebar:footer:bg", footer_x, footer_y, footer_w, footer_h, 15, 15, 15, 200, 12.0)
                                                                            
                                                                            -- Avatar (Imagem do Discord do Usuário com Check de Segurança)
                                                                            local avatar_img = (ts.imports and ts.imports.Visuals and ts.imports.Visuals.user_avatar)
                                                                                or (AstonExecutor.API.GetAvatarURL and AstonExecutor.API.GetAvatarURL())
                                                                                or "DefaultAvatar"
                                                                            
                                                                            -- if AstonExecutor.API.GetDiscordInfo then
                                                                            --     local d_info = AstonExecutor.API.GetDiscordInfo()
                                                                            --     if d_info and d_info.avatar then
                                                                            --         avatar_img = d_info.avatar
                                                                            --     end
                                                                            -- end
                                                                            
                                                                            if avatar_img and avatar_img ~= "DefaultAvatar" then
                                                                                local avatar_x = footer_x + 10
                                                                                local avatar_y = footer_y + 10
                                                                                local avatar_size = 40
                                                                                
                                                                                ts.utils.add_shadow("sidebar:footer:avatar_shadow", avatar_x - 2, avatar_y - 2, avatar_size + 4, avatar_size + 4, 0, 0, 0, 80, 15.0, 20.0)
                                                                                ts.utils.add_rect("sidebar:footer:avatar_border", avatar_x - 1, avatar_y - 1, avatar_size + 2, avatar_size + 2, ts.colors.theme[1], ts.colors.theme[2], ts.colors.theme[3], 100, 25.0)
                                                                                ts.utils.add_image("sidebar:footer:avatar", avatar_img, avatar_x, avatar_y, avatar_size, avatar_size, 255, 255, 255, 255, 50.0, 50.0)
                                                                            else
                                                                                -- Fallback para ícone se não houver imagem
                                                                                ts.utils.add_text("sidebar:footer:avatar", "\xef\x8a\xbd", footer_x + 12, footer_y + 14, 28.0, false, 255, 255, 255, 200, ts.font_awesome)
                                                                            end
                                                                            
                                                                            -- Nome do Usuário (Limitado se for muito longo)
                                                                            local display_name = originalUserName
                                                                            if #display_name > 12 then display_name = display_name:sub(1, 10) .. ".." end
                                                                            ts.utils.add_text("sidebar:footer:user", display_name, footer_x + 60, footer_y + 12, 13.5, false, 255, 255, 255, 255, "quicksand_bold")
                                                                            
                                                                            -- Cargo (Role) com cor personalizada
                                                                            ts.utils.add_text("sidebar:footer:role", role_name, footer_x + 60, footer_y + 28, 11.0, false, role_color[1], role_color[2], role_color[3], 255, "quicksand")
                                                                            
                                                                            -- Tempo de Key
                                                                            local key_time_val = (ts.menu_info and ts.menu_info.key_time) or "Lifetime"
                                                                            ts.utils.add_text("sidebar:footer:key", "Plano: " .. key_time_val, footer_x + 60, footer_y + 42, 10.0, false, 200, 200, 200, 255, "quicksand")
                                                                        end)
                                                                        ts.elements['group'] = LPH_NO_VIRTUALIZE(function(group_name, group_icon, tabs_count)
                                                                            if not group_name or group_name == "" then return false, 0 end
                                                                            ts.vars = ts.vars or {}
                                                                            ts.vars.group_states = ts.vars.group_states or {}
                                                                            ts.vars.sidebar_y = ts.vars.sidebar_y or 175
                                                                            
                                                                            local gs = ts.vars.group_states[group_name]
                                                                            if not gs then
                                                                                gs = { 
                                                                                    expanded = true,
                                                                                    height = 35.0,
                                                                                    alpha = 255.0 
                                                                                }
                                                                                ts.vars.group_states[group_name] = gs
                                                                            end
                                                                            
                                                                            local x = ts.x + 10
                                                                            local y = ts.y + ts.vars.sidebar_y + 8
                                                                            local w = 180
                                                                            local header_h = 36
                                                                            local tab_h = 32
                                                                            local spacing = 4
                                                                            
                                                                            local target_height = header_h + (gs.expanded and (tabs_count * (tab_h + spacing)) or 0)
                                                                            local target_alpha = gs.expanded and 255 or 0
                                                                            gs.height = ts.essentials.lerp(0.1, gs.height, target_height)
                                                                            gs.alpha = ts.essentials.lerp(0.12, gs.alpha, target_alpha)
                                                                            
                                                                            if ts.essentials.hovered(x, y, w, header_h) and not ts.combobox_click_handled then
                                                                                if AstonExecutor.API['IsKeyJustPressed'](0x01) then
                                                                                    gs.expanded = not gs.expanded
                                                                                    if PlaySoundFrontend then PlaySoundFrontend(-1, "NAV_UP_DOWN", "HUD_FRONTEND_DEFAULT_SOUNDSET", false) end
                                                                                end
                                                                            end
                                                                            
                                                                            -- Header do Grupo Estilizado
                                                                            local theme = ts.colors.theme
                                                                            ts.utils.add_text("group:icon:"..group_name, group_icon, x + 10, y + 10, 17.0, false, theme[1], theme[2], theme[3], 255, ts.font_awesome, 60)
                                                                            ts.utils.add_text("group:name:"..group_name, group_name, x + 42, y + 11, 12.0, false, 200, 200, 200, 255, "quicksand", 60)
                                                                            
                                                                            local arrow_char = gs.expanded and "\xef\x81\xb7" or "\xef\x81\xb8"
                                                                            ts.utils.add_text("group:arrow:"..group_name, arrow_char, x + w - 20, y + 11, 13.0, false, theme[1], theme[2], theme[3], 255, ts.font_awesome, 60)
                                                                            
                                                                            ts.vars.current_group_y = y + header_h + spacing
                                                                            ts.vars.current_group_alpha = gs.alpha
                                                                            ts.vars.sidebar_y = ts.vars.sidebar_y + gs.height + 8
                                                                            
                                                                            return gs.expanded, gs.alpha
                                                                        end)
                                                                        ts.elements['tab'] = LPH_NO_VIRTUALIZE(function(tab_name, icon, group_expanded, group_alpha, target_tab, target_subtab)
                                                                            if group_alpha <= 0 then return end
                                                                            
                                                                            ts.vars = ts.vars or {}
                                                                            ts.vars.sidebar_selected = ts.vars.sidebar_selected or ts.get_text("player")
                                                                            ts.vars.tab_selected = ts.vars.tab_selected or "Player"
                                                                            ts.vars.subtab_memory = ts.vars.subtab_memory or { ["Player"] = "Geral" }
                                                                            
                                                                            local x = ts.x + 18
                                                                            local y = ts.vars.current_group_y
                                                                            local w = 184
                                                                            local h = 34
                                                                            
                                                                            local t_tab = target_tab or tab_name
                                                                            local active = (ts.vars.tab_selected == t_tab)
                                                                            local is_hovered = ts.essentials.hovered(x, y, w, h)
                                                                            
                                                                            ts.animations = ts.animations or {}
                                                                            ts.animations.tabs = ts.animations.tabs or {}
                                                                            if not ts.animations.tabs[t_tab] then ts.animations.tabs[t_tab] = {0, 0} end -- [hover_anim, active_anim]
                                                                            
                                                                            ts.animations.tabs[t_tab][1] = ts.essentials.lerp(0.15, ts.animations.tabs[t_tab][1], is_hovered and 1 or 0)
                                                                            ts.animations.tabs[t_tab][2] = ts.essentials.lerp(0.15, ts.animations.tabs[t_tab][2], active and 1 or 0)
                                                                            
                                                                            local hover_a = ts.animations.tabs[t_tab][1]
                                                                            local active_a = ts.animations.tabs[t_tab][2]

                                                                            if is_hovered and not ts.combobox_click_handled and AstonExecutor.API['IsKeyJustPressed'](0x01) then
                                                                                ts.vars.tab_selected = t_tab
                                                                                -- Resetar vars de groupbox ao mudar de tab/subtab
                                                                                ts.vars.groupbox_current = nil
                                                                                ts.vars.groupbox_in_hover = nil
                                                                                ts.vars.groupbox_scrolls = nil
                                                                                ts.vars.groupbox_scroll_target = nil
                                                                                if PlaySoundFrontend then PlaySoundFrontend(-1, "NAV_LEFT_RIGHT", "HUD_FRONTEND_DEFAULT_SOUNDSET", false) end
                                                                                if target_subtab then
                                                                                    ts.vars.subtab_selected = target_subtab
                                                                                    ts.vars.subtab_memory[t_tab] = target_subtab
                                                                                else
                                                                                    ts.vars.subtab_selected = ts.vars.subtab_memory[t_tab] or "Geral"
                                                                                end
                                                                            end

                                                                            local theme = ts.colors.theme -- Usar o tema global
                                                                            local tr, tg, tb = theme[1], theme[2], theme[3]
                                                                            local tab_order = 2500
                                                                            
                                                                            -- Design de Tab Premium com Animações
                                                                            if active_a > 0.01 then
                                                                                -- Fundo sólido e contorno para a aba ativa
                                                                                ts.utils.add_rect("tab:active:bg:"..tab_name, x, y, w, h, tr, tg, tb, math.floor(group_alpha * active_a * 1.0), 10.0, tab_order)
                                                                                ts.utils.add_rect("tab:active:outline:"..tab_name, x, y, w, h, tr, tg, tb, math.floor(group_alpha * active_a * 0.8), 10.0, tab_order + 1, false, 1.2)
                                                                                ts.utils.add_shadow("tab:active:glow:"..tab_name, x, y, w, h, tr, tg, tb, math.floor(group_alpha * active_a * 0.25), 10.0, 8.0)
                                                                                
                                                                            elseif hover_a > 0.01 then
                                                                                ts.utils.add_rect("tab:hover:bg:"..tab_name, x, y, w, h, math.floor(tr * 0.1), math.floor(tg * 0.1), math.floor(tb * 0.1), math.floor(group_alpha * hover_a * 0.4), 10.0, tab_order)
                                                                                ts.utils.add_rect("tab:hover:outline:"..tab_name, x, y, w, h, tr, tg, tb, math.floor(group_alpha * hover_a * 0.3), 10.0, tab_order + 1, false, 0.6)
                                                                            end

                                                                            local text_color = active and {255, 255, 255} or (is_hovered and {tr, tg, tb} or {150, 150, 150})
                                                                            local icon_color = active and {255, 255, 255} or (is_hovered and {tr, tg, tb} or {100, 100, 100})
                                                                            
                                                                            if icon then
                                                                                ts.utils.add_text("tab:icon:"..tab_name, icon, x + 15 + (active_a * 5), y + (h / 2) - 6, 15.0, false, icon_color[1], icon_color[2], icon_color[3], math.floor(group_alpha), ts.font_awesome, tab_order + 3)
                                                                                ts.utils.add_text("tab:text:"..tab_name, tab_name, x + 50 + (active_a * 5), y + (h / 2) - 7, 12.5, false, text_color[1], text_color[2], text_color[3], math.floor(group_alpha), "quicksand", tab_order + 3)
                                                                            else
                                                                                ts.utils.add_text("tab:text:"..tab_name, tab_name, x + 15 + (active_a * 5), y + (h / 2) - 7, 12.5, false, text_color[1], text_color[2], text_color[3], math.floor(group_alpha), "quicksand", tab_order + 3)
                                                                            end
                                                                            
                                                                            ts.vars.current_group_y = ts.vars.current_group_y + h + 6
                                                                        end)

                                                                        ts.elements['begin_subtabs'] = LPH_NO_VIRTUALIZE(function()
                                                                            ts.vars.subtab_x = 245
                                                                            
                                                                        end)

                                                                        ts.elements['subtab'] = LPH_NO_VIRTUALIZE(function(name, target_id, icon)
                                                                            ts.vars = ts.vars or {}
                                                                            ts.vars.subtab_selected = ts.vars.subtab_selected or "Geral"
                                                                            ts.vars.subtab_x = ts.vars.subtab_x or 245
                                                                            
                                                                            local x = ts.x + ts.vars.subtab_x
                                                                            local y = ts.y + 14
                                                                            local text_w = ts.utils.text_width(name, 11.5, "quicksand_bold")
                                                                            local has_icon = (icon and icon ~= "")
                                                                            local w = text_w + (has_icon and 40 or 28)
                                                                            local h = 32
                                                                            local active = (ts.vars.subtab_selected == target_id)
                                                                            local hovered = ts.essentials.hovered(x, y, w, h)
                                                                            local theme = ts.colors.theme
                                                                            
                                                                            ts.animations = ts.animations or {}
                                                                            ts.animations.subtabs = ts.animations.subtabs or {}
                                                                            if not ts.animations.subtabs[target_id] then ts.animations.subtabs[target_id] = {0, 0} end
                                                                            
                                                                            local target_alpha = active and 1 or (hovered and 0.5 or 0)
                                                                            
                                                                            ts.animations.subtabs[target_id][1] = ts.essentials.lerp(0.15, ts.animations.subtabs[target_id][1], target_alpha)
                                                                            
                                                                            local active_a = ts.animations.subtabs[target_id][1]
                                                                            
                                                                            local theme = ts.colors.theme
                                                                            local tr, tg, tb = theme[1], theme[2], theme[3]
                                                                            
                                                                            if active_a > 0.01 then
                                                                                -- Active tab style (like the red one in the design)
                                                                                ts.utils.add_rect("subtab:active:bg:"..target_id, x, y, w, h, 25, 25, 30, math.floor(active_a * 255), 10.0)
                                                                                ts.utils.add_shadow("subtab:active:glow:"..target_id, x, y, w, h, tr, tg, tb, math.floor(active_a * 60), 12.0, 10.0)
                                                                            end
                                                                            
                                                                            if hovered and not ts.combobox_click_handled and AstonExecutor.API['IsKeyJustPressed'](0x01) then
                                                                                ts.vars.subtab_selected = target_id
                                                                                if PlaySoundFrontend then PlaySoundFrontend(-1, "NAV_UP_DOWN", "HUD_FRONTEND_DEFAULT_SOUNDSET", false) end
