                                                                                ts.vars.subtab_memory[ts.vars.tab_selected] = target_id
                                                                            end
                                                                            
                                                                            local text_color = active and {255, 255, 255} or (hovered and {220, 220, 225} or {170, 170, 180})
                                                                            local icon_color = active and {255, 255, 255} or (hovered and {tr, tg, tb} or {120, 120, 130})
                                                                            
                                                                            if has_icon then
                                                                                ts.utils.add_text("subtab:icon:"..target_id, icon, x + 12, y + 8, 13.0, false, icon_color[1], icon_color[2], icon_color[3], 255, ts.font_awesome, 65)
                                                                                ts.utils.add_text("subtab:text:"..target_id, name, x + 32, y + 8, 11.5, false, text_color[1], text_color[2], text_color[3], 255, "quicksand_bold", 65)
                                                                            else
                                                                                ts.utils.add_text("subtab:text:"..target_id, name, x + (w/2), y + 8, 11.5, true, text_color[1], text_color[2], text_color[3], 255, "quicksand_bold", 65)
                                                                            end
                                                                            
                                                                            ts.vars.subtab_x = ts.vars.subtab_x + w + 8
                                                                        end)

                                                                        ts.elements['search_bar'] = LPH_NO_VIRTUALIZE(function()
                                                                            -- Posição da barra de pesquisa encostada na borda
                                                                            local bar_w = 180
                                                                            local bar_h = 30
