                                                                            ts.utils.add_text("breadcrumb:sep1", ">", breadcrumb_x + 42, breadcrumb_y + 8, 12.0, false, 100, 100, 110, 255, "quicksand")
                                                                            
                                                                            local tab_name = ts.vars.tab_selected or "Jogador"
                                                                            ts.utils.add_text("breadcrumb:2_icon", "\xef\x81\x90", breadcrumb_x + 62, breadcrumb_y + 7, 13.0, false, tr, tg, tb, 255, ts.font_awesome)
                                                                            ts.utils.add_text("breadcrumb:2", tab_name, breadcrumb_x + 82, breadcrumb_y + 8, 12.0, false, 220, 220, 230, 255, "quicksand")
                                                                            
                                                                            ts.utils.add_text("breadcrumb:sep2", ">", breadcrumb_x + 82 + ts.utils.text_width(tab_name, 12.0, "quicksand") + 12, breadcrumb_y + 8, 12.0, false, 100, 100, 110, 255, "quicksand")
                                                                            
