                                                                                    ts.utils.add_shadow("right_sidebar:icon_glow:"..item.id, ix, iy, icon_box_size, icon_box_size, item.color[1], item.color[2], item.color[3], math.floor(main_anim * anim * 50), 10.0, 10.0)
                                                                                end

                                                                                local icon_color = item.color or {160, 160, 165}
                                                                                local tr, tg, tb = icon_color[1], icon_color[2], icon_color[3]
                                                                                if hovered then tr, tg, tb = 255, 255, 255 end
                                                                                
                                                                                ts.utils.add_text("right_sidebar:icon_text:"..item.id, item.icon, ix + (icon_box_size/2), iy + (icon_box_size/2) - 9, 17.0, true, tr, tg, tb, sidebar_alpha, ts.font_awesome)
                                                                                
                                                                                if hovered and AstonExecutor.API.IsKeyJustPressed(0x01) then
                                                                                    if item.cb then item.cb() end
                                                                                end

                                                                                -- Tooltip (Beautiful Effect Outside)
                                                                                if anim > 0.01 then
                                                                                    local tw = ts.utils.text_width(item.tooltip, 12.0, "quicksand") + 20
                                                                                    local tx = ix + icon_box_size + 15 - (anim * 5)
                                                                                    local ty = iy + (icon_box_size / 2) - 12
                                                                                    
                                                                                    ts.utils.add_shadow("right_sidebar:tooltip_shadow:"..item.id, tx, ty, tw, 24, 0, 0, 0, math.floor(anim * 100), 10.0, 6.0)
                                                                                    ts.utils.add_rect("right_sidebar:tooltip_bg:"..item.id, tx, ty, tw, 24, 15, 15, 18, math.floor(anim * 255), 6.0, 9999)
                                                                                    ts.utils.add_rect("right_sidebar:tooltip_outline:"..item.id, tx, ty, tw, 24, ts.colors.theme[1], ts.colors.theme[2], ts.colors.theme[3], math.floor(anim * 150), 6.0, 11, false, 0.8)
                                                                                    ts.utils.add_text("right_sidebar:tooltip_text:"..item.id, item.tooltip, tx + (tw/2), ty + 5, 12.0, true, 255, 255, 255, math.floor(anim * 255), "quicksand", 10000)
