                                                                        ts.elements['scroll'] = LPH_NO_VIRTUALIZE(function()
                                                                            if not ts or not ts.vars then return end
                                                                            
                                                                            if ts.vars.groupbox_in_hover and ts.vars.groupbox_in_hover ~= "none" then
                                                                                local last_box = ts.vars.groupbox_in_hover
                                                                                local scroll = (ts.vars.groupbox_scrolls and ts.vars.groupbox_scrolls[last_box]) or 0
                                                                                local groupboxes = ts.vars.groupboxes or {}
                                                                                local groupbox = groupboxes[last_box]
                                                                                if not groupbox then return end
                                                                                local content_height = groupbox.content_height or 0
                                                                                local add = 25
                                                                                
                                                                                ts.vars.groupbox_scroll_target = ts.vars.groupbox_scroll_target or {}
                                                                                if ts.vars.groupbox_scroll_target[last_box] == nil then
                                                                                    ts.vars.groupbox_scroll_target[last_box] = scroll
                                                                                end
                                                                                
                                                                                local view_h = groupbox.h - 66
                                                                                local min_scroll = math.min(0, view_h - content_height)
                                                                                
                                                                                -- Mouse Wheel Scroll
                                                                                if AstonExecutor.API.IsKeyPressed(0x100) then 
                                                                                    ts.vars.groupbox_scroll_target[last_box] = math.min(ts.vars.groupbox_scroll_target[last_box] + add, 0)
                                                                                end
                                                                                if AstonExecutor.API.IsKeyPressed(0x101) then 
                                                                                    ts.vars.groupbox_scroll_target[last_box] = math.max(ts.vars.groupbox_scroll_target[last_box] - add, min_scroll)
                                                                                end

                                                                                -- Scrollbar Drag Logic
                                                                                if content_height > view_h then
                                                                                    local track_w = 4
                                                                                    local track_x = groupbox.x + groupbox.w - track_w - 6
                                                                                    local track_y = groupbox.y + 61
                                                                                    local track_h = view_h
                                                                                    local thumb_h = math.max(40, (view_h / content_height) * track_h)
                                                                                    
                                                                                    local scroll_percent = math.abs(scroll) / math.abs(min_scroll)
                                                                                    local thumb_y = track_y + (scroll_percent * (track_h - thumb_h))
                                                                                    
                                                                                    local mouse_x, mouse_y = ts._frame_cursor_x, ts._frame_cursor_y
                                                                                    local dpi = dpi_menu or 1.0
                                                                                    local adj_m_x, adj_m_y = mouse_x / dpi, mouse_y / dpi
                                                                                    
                                                                                    -- Area de clique adaptada
                                                                                    local is_on_thumb = adj_m_x >= track_x - 10 and adj_m_x <= track_x + 15 and adj_m_y >= thumb_y and adj_m_y <= thumb_y + thumb_h
                                                                                    
                                                                                    if is_on_thumb and AstonExecutor.API.IsKeyJustPressed(0x01) then
                                                                                        ts.vars.dragging_scrollbar = last_box
                                                                                        ts.vars.drag_start_y = adj_m_y
                                                                                        ts.vars.drag_start_scroll = ts.vars.groupbox_scroll_target[last_box]
                                                                                    end
                                                                                end
                                                                                
                                                                                ts.vars.groupbox_scrolls = ts.vars.groupbox_scrolls or {}
                                                                                ts.vars.groupbox_scrolls[last_box] = ts.essentials.smoothlerp(0.25, scroll, ts.vars.groupbox_scroll_target[last_box])
                                                                            end

                                                                            -- Global dragging handle
                                                                            if ts.vars.dragging_scrollbar then
                                                                                if not AstonExecutor.API.IsKeyPressed(0x01) then
                                                                                    ts.vars.dragging_scrollbar = nil
                                                                                else
                                                                                    local last_box = ts.vars.dragging_scrollbar
                                                                                    local groupbox = ts.vars.groupboxes[last_box]
                                                                                    if groupbox then
                                                                                        local content_height = groupbox.content_height or 0
                                                                                    local view_h = groupbox.h - 66
                                                                                    local track_h = view_h
                                                                                        local min_scroll = math.min(0, view_h - content_height)
                                                                                        
                                                                                        local mouse_x, mouse_y = ts._frame_cursor_x, ts._frame_cursor_y
                                                                                        local dpi = dpi_menu or 1.0
                                                                                        local adj_m_y = mouse_y / dpi
                                                                                        
                                                                                        local dy = adj_m_y - ts.vars.drag_start_y
                                                                                        local scroll_move = (dy / (track_h - thumb_h)) * min_scroll
                                                                                        
                                                                                        ts.vars.groupbox_scroll_target[last_box] = math.max(min_scroll, math.min(0, ts.vars.drag_start_scroll + scroll_move))
                                                                                        ts.vars.groupbox_scrolls[last_box] = ts.vars.groupbox_scroll_target[last_box] -- Instant for dragging
                                                                                    end
                                                                                end
                                                                            end
                                                                        end)

                                                                        local function truncate_text(text, max_width, font, size)
                                                                            if not text or text == "" or not max_width or max_width <= 0 then return text or "" end
                                                                            local current_width = ts.utils.text_width(text, size, font) or 0
                                                                            if current_width <= max_width then return text end
                                                                            local ellipsis = "..."
                                                                            local truncated = text
                                                                            while #truncated > 0 and (ts.utils.text_width(truncated .. ellipsis, size, font) or 0) > max_width do
                                                                                truncated = truncated:sub(1, -2)
                                                                            end
                                                                            return truncated .. ellipsis
                                                                        end

                                                                        ts.elements['groupbox'] = LPH_NO_VIRTUALIZE(function(groupbox_name, groupbox_id, groupbox_icon, x, y, w, h, groupbox_description, addvalue_groupbox)
                                                                            if ts.search and ts.search.active then return end
                                                                            local dpi = dpi_menu
                                                                            local base_x = ts.x + 234
                                                                            local base_y = ts.y + 72
                                                                            local abs_x = base_x + (x or 0)
                                                                            local abs_y = base_y + (y or 0)
                                                                            ts.vars = ts.vars or {}
                                                                            ts.vars.groupboxes = ts.vars.groupboxes or {}
                                                                            
                                                                            -- Usar groupbox_id como chave para evitar bugs com traduções
                                                                            local gb_key = groupbox_id or groupbox_name
                                                                            local gb = ts.vars.groupboxes[gb_key]
                                                                            
                                                                            if not gb then
                                                                                gb = {
                                                                                    id = groupbox_id,
                                                                                    name = groupbox_name,
                                                                                    x = abs_x,
                                                                                    y = abs_y,
                                                                                    w = w,
                                                                                    h = h,
                                                                                    icon = groupbox_icon,
                                                                                    index = 0,
                                                                                    content_height = 0,
                                                                                    hover_smooth = 0,
                                                                                    active = true
                                                                                }
                                                                                ts.vars.groupboxes[gb_key] = gb
                                                                            else
                                                                                gb.active = true
                                                                                gb.index = 0
                                                                                gb.content_height = 0
                                                                                gb.name = groupbox_name -- Atualiza o nome traduzido
                                                                                if gb.x ~= abs_x then gb.x = abs_x end
                                                                                if gb.y ~= abs_y then gb.y = abs_y end
                                                                                if gb.w ~= w then gb.w = w end
                                                                                if gb.h ~= h then gb.h = h end
                                                                                if groupbox_icon ~= nil and gb.icon ~= groupbox_icon then
                                                                                    gb.icon = groupbox_icon
                                                                                end
                                                                                if gb.hover_smooth == nil then gb.hover_smooth = 0 end
                                                                            end
                                                                            local groupbox_draw_x = gb.x + 4
                                                                            local groupbox_draw_y = gb.y + 4
                                                                            local groupbox_draw_w = gb.w - 8
                                                                            local groupbox_draw_h = gb.h - 8
                                                                            local mouse_x, mouse_y = AstonExecutor.API['GetCursorX'](), AstonExecutor.API['GetCursorY']()
                                                                            local in_hover = false
                                                                            if mouse_x and mouse_y then
                                                                                local adj_mouse_x = mouse_x / dpi
                                                                                local adj_mouse_y = mouse_y / dpi
                                                                                in_hover = (adj_mouse_x >= groupbox_draw_x and adj_mouse_x <= groupbox_draw_x + groupbox_draw_w and adj_mouse_y >= groupbox_draw_y and adj_mouse_y <= groupbox_draw_y + groupbox_draw_h)
                                                                            end
                                                                            local lerp_speed = 0.25
                                                                            if in_hover then
                                                                                gb.hover_smooth = gb.hover_smooth + (1 - gb.hover_smooth) * lerp_speed
                                                                            else
                                                                                gb.hover_smooth = gb.hover_smooth + (0 - gb.hover_smooth) * lerp_speed
                                                                            end
                                                                            local hover_active = gb.hover_smooth > 0.5
                                                                            if hover_active then
                                                                                if ts.vars.groupbox_in_hover ~= gb_key then
                                                                                    ts.vars.groupbox_in_hover = gb_key
                                                                                end
                                                                            else
                                                                                if ts.vars.groupbox_in_hover == gb_key then
                                                                                    ts.vars.groupbox_in_hover = nil
                                                                                end
                                                                            end
                                                                            local gb_colors = ts.colors.groupbox
                                                                            local r, g, b = gb_colors[1], gb_colors[2], gb_colors[3]
                                                                            local theme = ts.colors.theme
                                                                            if ts.vars.current_gb_open then
                                                                                ts.utils.pop_clip("gb_clip")
                                                                                ts.vars.current_gb_open = nil
                                                                            end

                                                                            local title_text = groupbox_name or "Group"
                                                                            local header_y = groupbox_draw_y + 12
                                                                            
                                                                            if groupbox_icon then
                                                                                local theme = ts.colors.theme
                                                                                ts.utils.add_text("groupbox:icon:"..groupbox_id, groupbox_icon, groupbox_draw_x + 18, header_y, 19.0, false, theme[1], theme[2], theme[3], 255, ts.font_awesome)
                                                                            end
                                                                            ts.utils.add_text("groupbox:title:"..groupbox_id, title_text, groupbox_draw_x + 52, header_y - 1, 13.5, false, 255, 255, 255, 255, "quicksand_bold")
                                                                            
                                                                            -- Linha de destaque elegante abaixo do título com degradê
                                                                            local line_x = groupbox_draw_x + 15
                                                                            local line_y = header_y + 24
