                                                                                    vars.buttons_cache["checkbox:"..checkbox_id] = {
                                                                                        text = checkbox_name,
                                                                                        callback = cb,
                                                                                        type = "checkbox"
                                                                                    }
                                                                                end
                                                                                animations.checkbox = animations.checkbox or {}
                                                                                if not animations.checkbox[checkbox_id] then
                                                                                    animations.checkbox[checkbox_id] = { 50, 50, 50 }
                                                                                end
                                                                                animations.checkbox_marker = animations.checkbox_marker or {}
                                                                                animations.checkbox_marker[checkbox_id] = animations.checkbox_marker[checkbox_id] or 0
                                                                                ts.key_binds = ts.key_binds or {}
                                                                                if not ts.key_binds[checkbox_id] then
                                                                                    ts.key_binds[checkbox_id] = { label = "...", vk = nil, capturing = false, last_m2 = 0, cb = cb }
                                                                                end
                                                                                local keybind = ts.key_binds[checkbox_id]
                                                                                keybind.cb = cb

                                                                                local hovered = essentials.hovered(x, y, w, h)
                                                                                local checked = values.checkbox[checkbox_id]
                                                                                local keybind_text = (keybind.capturing and " [...]") or (keybind.vk and " ["..keybind.label.."]" or "")
                                                                                local box_x = x + w - 40 - 6
                                                                                local checkbox_display = truncate_text(checkbox_name .. keybind_text, box_x - (x + 10), "quicksand", 14.0)
                                                                                local theme = ts.colors.theme
                                                                                local br, bg, bb = theme[1], theme[2], theme[3]

                                                                                local lerp = essentials.lerp
                                                                                animations.checkbox_marker[checkbox_id] = lerp(0.2, animations.checkbox_marker[checkbox_id] or 0, checked and 1 or 0)
                                                                                local anim = animations.checkbox_marker[checkbox_id]
                                                                                
                                                                                -- Texto: Cinza normal, verde apenas quando hover
                                                                                local txt_r, txt_g, txt_b = 200, 200, 200
                                                                                if hovered then
                                                                                    txt_r, txt_g, txt_b = br, bg, bb
                                                                                end
                                                                                local txt_alpha = 230

                                                                                -- Texto alinhado à esquerda
                                                                                utils.add_text("checkbox:text:"..checkbox_id, checkbox_display, x + 5, y + (h / 2) - 7, 14.0, false, txt_r, txt_g, txt_b, txt_alpha, "quicksand")

                                                                                -- Design: bolinha verde apenas quando ativada
                                                                                local box_w = 40
                                                                                local box_h = 18
                                                                                local box_x = x + w - box_w - 6
                                                                                local box_y = y + (h / 2) - (box_h / 2)
                                                                                local circle_size = 14
                                                                                local circle_y = box_y + (box_h - circle_size) / 2
                                                                                local circle_x = box_x + 2 + ((box_w - circle_size - 4) * anim)

                                                                                -- Track sempre cinza escuro
                                                                                local track_bg_r, track_bg_g, track_bg_b = 50, 50, 50
                                                                                local track_bg_a = 200
                                                                                local outline_r, outline_g, outline_b = 80, 80, 80
                                                                                local outline_a = 180

                                                                                -- Bolinha: branca quando desativada, verde/tema quando ativada
                                                                                local circle_r, circle_g, circle_b = 255, 255, 255
                                                                                if checked then
                                                                                    circle_r, circle_g, circle_b = br, bg, bb
                                                                                end

                                                                                utils.add_shadow("checkbox:track_shadow:"..checkbox_id, box_x, box_y, box_w, box_h, 0, 0, 0, 60, 14.0, 8.0)
                                                                                utils.add_rect("checkbox:track_bg:"..checkbox_id, box_x, box_y, box_w, box_h, track_bg_r, track_bg_g, track_bg_b, track_bg_a, 10.0, 11, true, 1.0)
                                                                                utils.add_rect("checkbox:track_outline:"..checkbox_id, box_x, box_y, box_w, box_h, outline_r, outline_g, outline_b, outline_a, 10.0, 11, false, 1.2)

                                                                                utils.add_rect("checkbox:circle:"..checkbox_id, circle_x, circle_y, circle_size, circle_size, circle_r, circle_g, circle_b, 255, 18.0, 13, true, 1.0)
                                                                                if checked then
                                                                                    utils.add_shadow("checkbox:circle_glow:"..checkbox_id, circle_x - 1, circle_y - 1, circle_size + 2, circle_size + 2, br, bg, bb, 60, 18.0, 6.0)
                                                                                end

                                                                                local now = GetGameTimer and GetGameTimer() or 0
                                                                                if hovered and not ts.combobox_click_handled then
                                                                                    if AstonExecutor.API.IsKeyJustPressed and AstonExecutor.API.IsKeyJustPressed(0x01) then
                                                                                        if not ts._checkbox_last_pressed or not ts._checkbox_last_pressed[checkbox_id] then
                                                                                            values.checkbox[checkbox_id] = not values.checkbox[checkbox_id]
                                                                                            if cb then
                                                                                                sz.createTh(function()
                                                                                                    cb(values.checkbox[checkbox_id])
                                                                                                end)
                                                                                            end
                                                                                            ts._checkbox_last_pressed = ts._checkbox_last_pressed or {}
                                                                                            ts._checkbox_last_pressed[checkbox_id] = true
                                                                                        end
                                                                                    else
                                                                                        if ts._checkbox_last_pressed then
                                                                                            ts._checkbox_last_pressed[checkbox_id] = false
                                                                                        end
                                                                                    end
                                                                                    if AstonExecutor.API.IsKeyPressed and AstonExecutor.API.IsKeyPressed(0x02) then
                                                                                        if (not keybind.last_m2 or now - keybind.last_m2 > 500) then
                                                                                            keybind.capturing = true
                                                                                            keybind.last_m2 = now
                                                                                        end
                                                                                    end
                                                                                else
                                                                                    if ts._checkbox_last_pressed then
                                                                                        ts._checkbox_last_pressed[checkbox_id] = false
                                                                                    end
                                                                                end
                                                                                if keybind.capturing then
                                                                                    for k, vk in pairs(ts.keys) do
                                                                                        if k ~= "ESC" and k ~= "ENTER" and k ~= "Mouse Left" and k ~= "Mouse Right" then
                                                                                            if AstonExecutor.API.IsKeyJustPressed and AstonExecutor.API.IsKeyJustPressed(vk) then
                                                                                                keybind.vk = vk
                                                                                                keybind.label = k
                                                                                                keybind.capturing = false
                                                                                                if keybind.cb == nil then
                                                                                                    keybind.cb = cb
                                                                                                end
                                                                                            end
                                                                                        end
                                                                                    end
                                                                                    if AstonExecutor.API.IsKeyJustPressed and AstonExecutor.API.IsKeyJustPressed(0x08) then
                                                                                        keybind.vk = nil
                                                                                        keybind.label = "..."
                                                                                        keybind.capturing = false
                                                                                    end
                                                                                end
                                                                            end
                                                                            groupbox.index = (groupbox.index or 0) + h + 2 
                                                                            groupbox.content_height = (groupbox.content_height or 0) + h + 2
                                                                        end)
                                                                        ts.elements['slider'] = LPH_NO_VIRTUALIZE(function(slider_name, slider_id, slider_data, cb)
                                                                            local last_box = ts.vars.groupbox_current
                                                                            if not last_box then return end
                                                                            local groupboxes = ts.vars.groupboxes or {}
                                                                            local groupbox = groupboxes[last_box]
                                                                            if not groupbox then return end
                                                                            
                                                                            if groupbox.index == nil or type(groupbox.index) ~= "number" then groupbox.index = 0 end
                                                                            if groupbox.content_height == nil or type(groupbox.content_height) ~= "number" then groupbox.content_height = 0 end
                                                                            
                                                                            local scroll = ts.vars.groupbox_scrolls and ts.vars.groupbox_scrolls[last_box] or 0
                                                                            local x = (groupbox.x or 0) + 12
                                                                            local y = (groupbox.y or 0) + 61 + groupbox.index + scroll 
                                                                            local w = (groupbox.w or 100) - 24
                                                                            local h = 18
                                                                            
                                                                            local groupbox_top = (groupbox.y or 0) + 56
                                                                            local groupbox_bottom = (groupbox.y or 0) + (groupbox.h or 0) - 5
                                                                            
                                                                            if y + h >= groupbox_top and y <= groupbox_bottom then
                                                                                local minValue = slider_data.min or 0
                                                                                local maxValue = slider_data.max or 100
                                                                                local startValue = slider_data.start or minValue
                                                                                
                                                                                ts.values = ts.values or {}
                                                                                ts.values.slider = ts.values.slider or {}
                                                                                if ts.values.slider[slider_id] == nil then
                                                                                    ts.values.slider[slider_id] = startValue    
                                                                                end
                                                                                
                                                                                -- Clamp value
                                                                                if ts.values.slider[slider_id] < minValue then ts.values.slider[slider_id] = minValue end
                                                                                if ts.values.slider[slider_id] > maxValue then ts.values.slider[slider_id] = maxValue end

                                                                                local value_text = "["..tostring(ts.values.slider[slider_id]).."]"
                                                                                local value_w = ts['utils']['text_width'](value_text, 14.0, "quicksand") or 0
                                                                                local max_label_w = math.max(0, w - value_w - 60)
                                                                                local slider_label = truncate_text(slider_name, max_label_w, "quicksand", 14.0)
                                                                                local text_w = ts['utils']['text_width'](slider_label, 14.0, "quicksand") or 0
                                                                                
                                                                                local slider_bar_x = x + 5 + text_w + 10 + value_w + 10
                                                                                local slider_bar_y = y + (h / 2) - 2
                                                                                local slider_bar_w = w - (slider_bar_x - x) - 5
                                                                                local slider_bar_h = 4
                                                                                
                                                                                local hovered_full = ts.essentials.hovered(x, y, w, h)
                                                                                local hovered_bar = ts.essentials.hovered(slider_bar_x - 5, slider_bar_y - 5, slider_bar_w + 10, slider_bar_h + 10)
                                                                                
                                                                                ts.animations = ts.animations or {}
                                                                                ts.animations.slider_active = ts.animations.slider_active or {}
                                                                                ts.animations.slider_width = ts.animations.slider_width or {}
                                                                                if not ts.animations.slider_width[slider_id] then ts.animations.slider_width[slider_id] = 0 end
                                                                                
                                                                                if hovered_bar and not ts.combobox_click_handled and AstonExecutor.API.IsKeyJustPressed(0x01) then
                                                                                    ts.animations.slider_active[slider_id] = true
                                                                                end
                                                                                
                                                                                if ts.animations.slider_active[slider_id] then
                                                                                    if AstonExecutor.API.IsKeyPressed(0x01) then
                                                                                        local mousex = AstonExecutor.API.GetCursorX()
                                                                                        local dpi = ts.dpi_menu or 1
                                                                                        local bar_x_screen = slider_bar_x * dpi
                                                                                        local bar_w_screen = slider_bar_w * dpi
                                                                                        
                                                                                        local rel_x = (mousex - bar_x_screen) / bar_w_screen
                                                                                        local percent = math.max(0.0, math.min(1.0, rel_x))
                                                                                        
                                                                                        local newValue = minValue + (percent * (maxValue - minValue))
                                                                                        if math.type(minValue) == "integer" and math.type(maxValue) == "integer" then
                                                                                            newValue = math.floor(newValue + 0.5)
                                                                                        else
                                                                                            newValue = tonumber(string.format("%.2f", newValue))
                                                                                        end
                                                                                        
                                                                                        if ts.values.slider[slider_id] ~= newValue then
                                                                                            ts.values.slider[slider_id] = newValue
                                                                                            if cb then cb(newValue) end
                                                                                        end
                                                                                    else
                                                                                        ts.animations.slider_active[slider_id] = false
                                                                                    end
                                                                                end
                                                                                
                                                                                local percent = (ts.values.slider[slider_id] - minValue) / (maxValue - minValue)
                                                                                ts.animations.slider_width[slider_id] = ts.essentials.lerp(0.15, ts.animations.slider_width[slider_id], percent * slider_bar_w)
                                                                                local sw = ts.animations.slider_width[slider_id]
                                                                                local theme = ts.colors.theme
                                                                                
                                                                                local theme = ts.colors.theme
                                                                                local br, bg, bb = theme[1], theme[2], theme[3]
                                                                                local text_alpha = hovered_full and 255 or 150
                                                                                
                                                                                ts.utils.add_text("slider:text:"..slider_id, slider_label, x + 5, y + (h / 2) - 7, 14.0, false, 255, 255, 255, text_alpha, "quicksand")
                                                                                ts.utils.add_text("slider:val:"..slider_id, value_text, x + 5 + text_w + 10, y + (h / 2) - 7, 14.0, false, br, bg, bb, text_alpha, "quicksand")
                                                                                
                                                                                ts.utils.add_shadow("slider:shadow:"..slider_id, slider_bar_x, slider_bar_y, slider_bar_w, 4, 0, 0, 0, 150, 10.0, 6.0)
                                                                                ts.utils.add_gradient("slider:bg:"..slider_id, slider_bar_x, slider_bar_y, slider_bar_w, 4, 15, 15, 15, 255, 10, 10, 10, 255, 50.0)
                                                                                
                                                                                ts.utils.add_rect("slider:outline:"..slider_id, slider_bar_x - 1, slider_bar_y - 1, slider_bar_w + 2, 6, 40, 40, 40, 150, 50.0, 10, false, 1.0)
                                                                                
                                                                                if sw > 0 then
                                                                                    ts.utils.add_gradient("slider:fg:"..slider_id, slider_bar_x, slider_bar_y, sw, 4, br, bg, bb, 255, br*0.6, bg*0.6, bb*0.6, 255, 50.0)
                                                                                end
                                                                                
                                                                                local knob_size = 10
                                                                                local knob_x = slider_bar_x + sw
                                                                                local knob_y = slider_bar_y + (slider_bar_h / 2)
                                                                                ts.utils.add_rect("slider:knob:"..slider_id, knob_x - (knob_size/2), knob_y - (knob_size/2), knob_size, knob_size, 255, 255, 255, 255, 50.0)
                                                                                ts.utils.add_shadow("slider:knob_shadow:"..slider_id, knob_x - (knob_size/2), knob_y - (knob_size/2), knob_size, knob_size, 0, 0, 0, 120, 50.0, 6.0)
                                                                                
                                                                                if hovered_full then
                                                                                    ts.utils.add_shadow("slider:fill_glow:"..slider_id, slider_bar_x, slider_bar_y, sw, 4, br, bg, bb, 50, 10.0, 50.0)
                                                                                end
                                                                            end
                                                                            groupbox.index = (groupbox.index or 0) + h + 2
                                                                            groupbox.content_height = (groupbox.content_height or 0) + h + 2
                                                                        end)
                                                                        ts.elements['input'] = LPH_NO_VIRTUALIZE(function(input_title, input_id, placeholder, search_or_icon)
                                                                            local last_box = ts.vars.groupbox_current
                                                                            if not last_box then return end
                                                                            local groupboxes = ts.vars.groupboxes or {}
                                                                            local groupbox = groupboxes[last_box]
                                                                            if not groupbox then return end
                                                                            
                                                                            if groupbox.index == nil or type(groupbox.index) ~= "number" then groupbox.index = 0 end
                                                                            if groupbox.content_height == nil or type(groupbox.content_height) ~= "number" then groupbox.content_height = 0 end
                                                                            
                                                                            local scroll = ts.vars.groupbox_scrolls and ts.vars.groupbox_scrolls[last_box] or 0
                                                                            local x = (groupbox.x or 0) + 12
                                                                            local y = (groupbox.y or 0) + 61 + groupbox.index + scroll 
                                                                            local w = (groupbox.w or 100) - 24
                                                                            local h = 20
                                                                            
                                                                            local groupbox_top = (groupbox.y or 0) + 56
                                                                            local groupbox_bottom = (groupbox.y or 0) + (groupbox.h or 0) - 5
                                                                            
                                                                            if y + h >= groupbox_top and y <= groupbox_bottom then
                                                                                ts.values = ts.values or {}
                                                                                ts.values.input = ts.values.input or {}
                                                                                if not ts.values.input[input_id] then
                                                                                    ts.values.input[input_id] = ''
                                                                                end
                                                                                
                                                                                local title_text = truncate_text(input_title .. ": ", math.max(0, w - 160), 'quicksand', 16.0)
                                                                                local title_width = ts['utils']['text_width'](title_text, 16.0, 'quicksand') or 0
                                                                                
                                                                                -- Centraliza vertical e horizontalmente todo o conjunto (Ícone + Texto + Input Box)
                                                                                local total_content_w = 20 + title_width + 10 + 120 -- 120 é a largura baseada que daremos pro input box
                                                                                local start_x = x + ((w - total_content_w) / 2)
                                                                                
                                                                                local input_box_x = start_x + 23 + title_width + 5
                                                                                local input_box_w = 120 -- Largura fixa para manter proporção e não colar na borda direita
                                                                                local input_box_y = y + 3
                                                                                local input_box_h = 18
                                                                                
                                                                                local hovered = ts.essentials.hovered(x, y, w, h)
                                                                                local typing = ts.text_input and ts.text_input.active == input_id
                                                                                
                                                                                ts.animations = ts.animations or {}
                                                                                ts.animations.input = ts.animations.input or {}
                                                                                if not ts.animations.input[input_id] then ts.animations.input[input_id] = { 50, 50, 50 } end
                                                                                
                                                                                local target_color = typing and {220, 220, 220} or (hovered and {180, 180, 180} or {50, 50, 50})
                                                                                for i=1,3 do ts.animations.input[input_id][i] = ts.essentials.lerp(0.1, ts.animations.input[input_id][i], target_color[i]) end
                                                                                
                                                                                local cr, cg, cb = math.ceil(ts.animations.input[input_id][1]), math.ceil(ts.animations.input[input_id][2]), math.ceil(ts.animations.input[input_id][3])
                                                                                
                                                                                -- Ícone padrão baseado no search_or_icon
                                                                                local icon_to_draw = "\xef\x81\x84" -- Default icon
                                                                                if search_or_icon == true then
                                                                                    icon_to_draw = "\xef\x80\x82" -- Search icon
                                                                                elseif type(search_or_icon) == "string" and #search_or_icon > 0 and #search_or_icon < 4 then
                                                                                    icon_to_draw = search_or_icon -- Custom icon (glyph)
                                                                                end
                                                                                
                                                                                local icon_font = ts.font_awesome
                                                                                ts['utils']['add_text']('input:icon' ..input_id, icon_to_draw, start_x + 2, y + 4, 14.0, false, ts.colors.theme[1], ts.colors.theme[2], ts.colors.theme[3], 255, icon_font, 20)
                                                                                
                                                                                ts['utils']['add_text']("input:text:"..input_id, title_text, start_x + 23, y + 4, 16.0, false, cr, cg, cb, 255, "quicksand", 10)
                                                                                local theme = ts.colors.theme
                                                                                local bg_val = typing and 22 or (hovered and 26 or 18)
                                                                                
                                                                                -- Fundo do input Simples
                                                                                ts.utils.add_rect("input:bg:"..input_id, input_box_x, input_box_y, input_box_w, input_box_h, bg_val, bg_val, bg_val, 255, 6.0)
                                                                                
                                                                                local outline_alpha = typing and 80 or (hovered and 50 or 20)
                                                                                local outline_color = typing and {255, 255, 255} or (hovered and {150, 150, 150} or {60, 60, 60})
                                                                                ts['utils']['add_rect']("input:outline:"..input_id, input_box_x, input_box_y, input_box_w, input_box_h, outline_color[1], outline_color[2], outline_color[3], outline_alpha, 6.0, 11, false, 0.5)
                                                                                
                                                                                local current_input = ts.values.input[input_id]
                                                                                local display_text = current_input
                                                                                local is_placeholder = false
                                                                                
                                                                                if #current_input == 0 and placeholder and #placeholder > 0 then
                                                                                    display_text = placeholder
                                                                                    is_placeholder = true
                                                                                end
                                                                                
                                                                                local text_color = typing and {255, 255, 255} or (is_placeholder and {100, 100, 100} or {180, 180, 180})
                                                                                
                                                                                local max_display_w = input_box_w - 10
                                                                                local current_display_text = display_text
                                                                                
                                                                                -- Só faz scroll se não for placeholder
                                                                                if not is_placeholder then
                                                                                    while ts['utils']['text_width'](current_display_text, 14.0, "quicksand") > max_display_w and #current_display_text > 0 do
                                                                                        current_display_text = current_display_text:sub(2)
                                                                                    end
                                                                                else
                                                                                    -- Se for placeholder e muito longo, corta com ...
                                                                                    if ts['utils']['text_width'](current_display_text, 14.0, "quicksand") > max_display_w then
                                                                                        while ts['utils']['text_width'](current_display_text .. "...", 14.0, "quicksand") > max_display_w and #current_display_text > 0 do
                                                                                            current_display_text = current_display_text:sub(1, -2)
                                                                                        end
                                                                                        current_display_text = current_display_text .. "..."
                                                                                    end
                                                                                end
                                                                                
                                                                                ts['utils']['add_text']("input:value:"..input_id, current_display_text, input_box_x + 5, input_box_y + 2, 14.0, false, text_color[1], text_color[2], text_color[3], 255, "quicksand", 11)
                                                                                
                                                                                if typing then
                                                                                    local text_w = ts['utils']['text_width'](current_display_text, 14.0, 'quicksand') or 0
                                                                                    if GetGameTimer() % 1000 < 500 then
                                                                                        ts['utils']['add_rect']("input:cursor:"..input_id, input_box_x + 5 + text_w + 1, input_box_y + 3, 1, 12, 255, 255, 255, 255, 0.0, 12)
                                                                                    end
                                                                                end
                                                                                
                                                                                if hovered and not ts.combobox_click_handled and AstonExecutor.API.IsKeyPressed(0x01) then
                                                                                    ts.text_input = ts.text_input or {}
                                                                                    if ts.text_input.active ~= input_id then
                                                                                        ts.text_input.active = input_id
                                                                                        sz.createTh(function()
                                                                                            local cooldowns = {}
                                                                                            while ts.text_input.active == input_id and ts.active do
                                                                                                if AstonExecutor.API.IsKeyPressed(0x0D) or (not ts.essentials.hovered(ts.x, ts.y, ts.w, ts.h) and AstonExecutor.API.IsKeyPressed(0x01)) then 
                                                                                                    break 
                                                                                                end
                                                                                                
                                                                                                if AstonExecutor.API.IsKeyPressed(0x08) then
                                                                                                    local cd = cooldowns[0x08] or 0
                                                                                                    if GetGameTimer() - cd > 150 then
                                                                                                        ts.values.input[input_id] = ts.values.input[input_id]:sub(1, -2)
                                                                                                        cooldowns[0x08] = GetGameTimer() - 50
                                                                                                    end
                                                                                                else
                                                                                                    cooldowns[0x08] = 0
                                                                                                end
                                                                                                
                                                                                                local shift = AstonExecutor.API.IsKeyPressed(0x10)
                                                                                                for key, vk in pairs(ts.keys) do
                                                                                                    if #key == 1 and vk ~= 0x01 and vk ~= 0x02 then
                                                                                                        if AstonExecutor.API.IsKeyPressed(vk) then
                                                                                                            local cd = cooldowns[vk] or 0
                                                                                                            if GetGameTimer() - cd > 200 then
                                                                                                                local char = key
                                                                                                                if not shift then char = string.lower(char) end
                                                                                                                ts.values.input[input_id] = ts.values.input[input_id] .. char
                                                                                                                cooldowns[vk] = GetGameTimer()
                                                                                                            end
                                                                                                        else
                                                                                                            cooldowns[vk] = 0
                                                                                                        end
                                                                                                    end
                                                                                                end
                                                                                                Wait(0)
                                                                                            end
                                                                                            if ts.text_input.active == input_id then ts.text_input.active = nil end
                                                                                        end)
                                                                                    end
                                                                                end
                                                                            end
                                                                            groupbox.index = (groupbox.index or 0) + h + 5
                                                                            groupbox.content_height = (groupbox.content_height or 0) + h + 5
                                                                        end)
                                                                        ts.elements['list'] = LPH_NO_VIRTUALIZE(function(value, selected, callback, text)
                                                                            if not ts.vars or not ts.vars.groupbox_current then return end
                                                                            local last_box = ts.vars.groupbox_current
                                                                            local groupboxes = ts.vars.groupboxes or {}
                                                                            local groupbox = groupboxes[last_box]
                                                                            if not groupbox then return end

                                                                            if groupbox.index == nil or type(groupbox.index) ~= "number" then groupbox.index = 0 end
                                                                            if groupbox.content_height == nil or type(groupbox.content_height) ~= "number" then groupbox.content_height = 0 end
                                                                            
                                                                            local scroll = ts.vars.groupbox_scrolls and ts.vars.groupbox_scrolls[last_box] or 0
                                                                            local x = (groupbox.x or 0) + 18
                                                                            local y = (groupbox.y or 0) + 55 + groupbox.index + scroll
                                                                            local w = (groupbox.w or 100) - 36
                                                                            local h = 24
                                                                            local groupbox_top = (groupbox.y or 0) + 56
                                                                            local groupbox_bottom = (groupbox.y or 0) + (groupbox.h or 0) - 5
                                                                            local button_tag = last_box .. '_list_' .. tostring(value)
                                                                            ts.hoverStates = ts.hoverStates or {}
                                                                            ts.animations = ts.animations or {}
                                                                            ts.animations.button = ts.animations.button or {}
                                                                            
                                                                            local hovered = ts.essentials.hovered(x, y, w, h)
                                                                            if hovered then
                                                                                ts.hoverStates[last_box] = button_tag
                                                                            elseif ts.hoverStates[last_box] == button_tag then
                                                                                ts.hoverStates[last_box] = nil
                                                                            end
                                                                            
                                                                            local is_hovered = ts.hoverStates[last_box] == button_tag
                                                                            local theme = ts.colors.theme
                                                                            
                                                                            if not ts.animations.button[button_tag] then
                                                                                ts.animations.button[button_tag] = { 150, 150, 150 }
                                                                            end
                                                                            ts.animations.button[button_tag][1] = ts.essentials.lerp(0.12, ts.animations.button[button_tag][1], (is_hovered or selected) and 255 or 150)
                                                                            local cc = math.ceil(ts.animations.button[button_tag][1])
                                                                            
                                                                            -- Background sutil para lista (novo design)
                                                                            local bg_alpha_top = selected and 50 or (is_hovered and 30 or 0)
                                                                            local bg_alpha_bot = selected and 30 or (is_hovered and 15 or 0)
                                                                            if bg_alpha_top > 0 then
                                                                                ts.utils.add_gradient("list2:bg:"..button_tag, x, y, w, h, theme[1], theme[2], theme[3], bg_alpha_top, theme[1], theme[2], theme[3], bg_alpha_bot, 5.0)
                                                                                -- Borda branca suave
                                                                                ts.utils.add_rect("list2:outline:"..button_tag, x, y, w, h, 255, 255, 255, selected and 50 or 20, 5.0, 11, false, 1.0)
                                                                            end
                                                                            
                                                                            local display_text = truncate_text(text or tostring(value), w - 30, 'quicksand', 14.0)
                                                                            -- Centralizado vertical e horizontalmente
                                                                            ts.utils.add_text('list:text:'..button_tag, display_text, x + (w / 2), y + 2, 14.0, true, cc, cc, cc, 255, 'quicksand')
                                                                            
                                                                            if selected then
                                                                                ts.utils.add_rect("list:marker:"..button_tag, x + 2, y + 4, 2, 16, theme[1], theme[2], theme[3], 255, 50.0)
                                                                            end

                                                                            if is_hovered and not ts.combobox_click_handled and callback and AstonExecutor.API.IsKeyPressed and AstonExecutor.API.IsKeyPressed(0x01) then
                                                                                if not ts._listbutton_last_pressed or not ts._listbutton_last_pressed[button_tag] then
                                                                                    ts._listbutton_last_pressed = ts._listbutton_last_pressed or {}
                                                                                    ts._listbutton_last_pressed[button_tag] = true
                                                                                    sz.createTh(function()
                                                                                        callback()
                                                                                    end)
                                                                                end
                                                                            else
                                                                                if ts._listbutton_last_pressed then
                                                                                    ts._listbutton_last_pressed[button_tag] = false
                                                                                end
                                                                            end
                                                                            
                                                                            groupbox.index = (groupbox.index or 0) + h + 5
                                                                            groupbox.content_height = (groupbox.content_height or 0) + h + 5
                                                                        end)
                                                                        ts.elements['draw_scrollbars'] = LPH_NO_VIRTUALIZE(function()
                                                                            if not ts or not ts.vars or not ts.vars.groupboxes then return end
                                                                            
                                                                            for name, gb in pairs(ts.vars.groupboxes) do
                                                                                -- Só desenha se a box está ativa neste frame
                                                                                if gb.active then
                                                                                    local view_h = gb.h - 66
                                                                                    local content_h = gb.content_height or 0
                                                                                    
                                                                                    -- Posicionamento adaptado ao tamanho da groupbox
                                                                                    local track_w = 4
                                                                                    local track_x = gb.x + gb.w - track_w - 6
                                                                                    local track_y = gb.y + 61
                                                                                    local track_h = view_h
                                                                                    
                                                                                    if track_h > 0 then
                                                                                        local theme = ts.colors.theme
                                                                                        local is_dragging = ts.vars.dragging_scrollbar == name
                                                                                        local is_hovered = ts.essentials.hovered(track_x - 6, track_y, track_w + 12, track_h)
                                                                                        
                                                                                        -- Track (Fundo da barra) - Sempre visível se a box existe
                                                                                        ts.utils.add_rect("scrollbar:track:"..name, track_x, track_y, track_w, track_h, 30, 30, 30, 120, 20.0, 100)
                                                                                        
                                                                                        -- Thumb (A parte que mexe) - Só se houver overflow
                                                                                        if content_h > view_h then
                                                                                            local scroll = (ts.vars.groupbox_scrolls and ts.vars.groupbox_scrolls[name]) or 0
                                                                                            local min_scroll = view_h - content_h
                                                                                            
                                                                                            -- Cálculo do tamanho e posição do thumb (evita divisão por zero)
                                                                                            local thumb_h = math.max(40, (view_h / content_h) * track_h)
                                                                                            local scroll_percent = 0
                                                                                            if math.abs(min_scroll) > 0.001 then
                                                                                                scroll_percent = math.abs(scroll) / math.abs(min_scroll)
                                                                                            end
                                                                                            local thumb_y = track_y + (scroll_percent * (track_h - thumb_h))
                                                                                            
                                                                                            local thumb_alpha = is_dragging and 255 or (is_hovered and 220 or 150)
                                                                                            local thumb_r, thumb_g, thumb_b = theme[1], theme[2], theme[3]
                                                                                            
                                                                                            -- Thumb principal
                                                                                            ts.utils.add_rect("scrollbar:thumb:"..name, track_x, thumb_y, track_w, thumb_h, thumb_r, thumb_g, thumb_b, thumb_alpha, 20.0, 101)
                                                                                            
                                                                                            -- Efeito de brilho ao interagir
                                                                                            if is_dragging or is_hovered then
                                                                                                local glow_alpha = is_dragging and 100 or 50
                                                                                                ts.utils.add_shadow("scrollbar:glow:"..name, track_x - 1, thumb_y, track_w + 2, thumb_h, thumb_r, thumb_g, thumb_b, glow_alpha, 10.0, 20.0, 102)
                                                                                            end
                                                                                        end
                                                                                    end
                                                                                end
                                                                            end
                                                                        end)

                                                                        ts.elements['render_notify'] = LPH_NO_VIRTUALIZE(function()
                                                                            local cur_time = GetGameTimer()
                                                                            local sW = ts._frame_sW or 1920
                                                                            local sH = ts._frame_sH or 1080
                                                                            local base_y = 40 -- Um pouco mais para baixo
                                                                            local spacing = 85 -- Um pouco mais de espaço
                                                                            
                                                                            local function ease_out_cubic(t)
                                                                                return 1 - math.pow(1 - t, 3)
                                                                            end

                                                                            local function smooth_lerp(alpha, from, to)
                                                                                alpha = math.max(0, math.min(1, alpha or 0.12))
                                                                                return from + (to - from) * alpha
                                                                            end

                                                                            local anim_time = 700 
                                                                            local lerp_alpha_in = 0.15 
                                                                            local lerp_alpha_out = 0.12 
                                                                            
                                                                            local notify_types = ts.notify_types
                                                                            if not ts.notifications then return end
                                                                            
                                                                            for i = #ts.notifications, 1, -1 do
                                                                                local notify = ts.notifications[i]
                                                                                local ntype = notify_types[notify.type] or notify_types.info
                                                                                local elapsed = cur_time - notify.time
                                                                                
                                                                                -- Medir largura dos textos
                                                                                local title_translated = ts.get_text(ntype.title)
                                                                                local title_width = ts.utils.text_width(title_translated, 18.0, 'quicksand')
                                                                                local text_width = ts.utils.text_width(notify.text, 14.0, 'quicksand')
                                                                                
                                                                                -- Layout
                                                                                local icon_size = 24.0
                                                                                local padding_left = 15
                                                                                local icon_to_text = 15
                                                                                local padding_right = 25
                                                                                local content_width = math.max(title_width, text_width)
                                                                                local total_width = padding_left + icon_size + icon_to_text + content_width + padding_right
                                                                                local min_width = 250
                                                                                if total_width < min_width then total_width = min_width end
                                                                                
                                                                                local rect_width = total_width
                                                                                local rect_height = 65
                                                                                local base_x = sW - rect_width - 30
                                                                                local y = base_y + (i-1) * spacing
                                                                                
                                                                                -- Progresso
                                                                                local progress = 1 - (elapsed / notify.duration)
                                                                                if progress < 0 then progress = 0 end
                                                                                local bar_width = rect_width * progress
                                                                                
                                                                                -- Animação suave de entrada/saída
                                                                                if elapsed < anim_time then
                                                                                    local t = elapsed / anim_time
                                                                                    local alpha_anim = ease_out_cubic(t)
                                                                                    notify.x = sW - (sW - base_x) * alpha_anim
                                                                                    notify.alpha = math.floor(255 * alpha_anim)
                                                                                elseif elapsed > (notify.duration - anim_time) then
                                                                                    local t = (notify.duration - elapsed) / anim_time
                                                                                    local alpha_anim = ease_out_cubic(t)
                                                                                    notify.x = sW - (sW - base_x) * alpha_anim
                                                                                    notify.alpha = math.floor(255 * alpha_anim)
                                                                                else
                                                                                    notify.x = base_x
                                                                                    notify.alpha = 255
                                                                                end
                                                                                
                                                                                local nx = notify.x
                                                                                local nalpha = notify.alpha
                                                                                
                                                                                -- Sombra/Glow Suave
                                                                                ts.utils.add_shadow("notify:glow" .. notify.id, nx, y, rect_width, rect_height, ntype.color[1], ntype.color[2], ntype.color[3], math.floor(nalpha * 0.15), 18.0, 12.0)
                                                                                ts.utils.add_shadow("notify:shadow" .. notify.id, nx, y, rect_width, rect_height, 0, 0, 0, math.floor(nalpha * 0.4), 22.0, 14.0)
                                                                                
                                                                                -- Background com Gradiente Sutil
                                                                                ts.utils.add_gradient("notify:bg" .. notify.id, nx, y, rect_width, rect_height, 18, 18, 18, nalpha, 12, 12, 12, nalpha, 14.0)
                                                                                
                                                                                -- Borda/Outline sutil
                                                                                ts.utils.add_rect("notify:outline" .. notify.id, nx, y, rect_width, rect_height, 255, 255, 255, math.floor(nalpha * 0.08), 14.0, 1, false, 1.2)
                                                                                
                                                                                -- Barra de Destaque Lateral (Glow)
                                                                                ts.utils.add_rect("notify:accent" .. notify.id, nx, y + 10, 3, rect_height - 20, ntype.color[1], ntype.color[2], ntype.color[3], nalpha, 2.0)
                                                                                ts.utils.add_shadow("notify:accent:glow" .. notify.id, nx, y + 10, 3, rect_height - 20, ntype.color[1], ntype.color[2], ntype.color[3], math.floor(nalpha * 0.5), 8.0, 2.0)
                                                                                
                                                                                -- Ícone
                                                                                ts.utils.add_text("notify:icon" .. notify.id, ntype.icon, nx + padding_left, y + (rect_height/2) - (icon_size/2), icon_size, false, ntype.color[1], ntype.color[2], ntype.color[3], nalpha, ts.font_awesome)
                                                                                
                                                                                -- Textos
                                                                                local text_x = nx + padding_left + icon_size + icon_to_text
                                                                                ts.utils.add_text("notify:title" .. notify.id, title_translated, text_x, y + 12, 17.0, false, 255, 255, 255, nalpha, 'quicksand')
                                                                                ts.utils.add_text("notify:text" .. notify.id, notify.text, text_x, y + 34, 13.0, false, 200, 200, 200, nalpha, 'quicksand')
                                                                                
                                                                                -- Barra de Progresso com Gradiente
                                                                                if progress > 0 then
                                                                                    ts.utils.add_gradient("notify:bar" .. notify.id, nx + 10, y + rect_height - 4, bar_width - 20, 2, ntype.color[1], ntype.color[2], ntype.color[3], math.floor(nalpha * 0.7), ntype.color[1], ntype.color[2], ntype.color[3], math.floor(nalpha * 0.3), 1.0)
                                                                                end
                                                                                
                                                                                if elapsed > notify.duration and notify.x >= sW then
                                                                                    table.remove(ts.notifications, i)
                                                                                end
                                                                            end
                                                                        end)
                                                                        ts.elements['notify'] = LPH_NO_VIRTUALIZE(function(text, type, duration)
