                                                                                                        FreezeEntityPosition(pedId, false)
                                                                                                        NetworkSetEntityInvisibleToNetwork(pedId, false)
                                                                                                    end

                                                                                                    local noclip_speed = ts.values.slider and ts.values.slider["noclip_speed_atz"] or 1.0
                                                                                                    local isInVehicle = IsPedInAnyVehicle(pedId, false)
