                                                                                                SetEntityCollision(targetEntity, true, true)
                                                                                                SetEntityVisible(targetEntity, true, 0)
                                                                                                FreezeEntityPosition(targetEntity, false)
                                                                                                NetworkSetEntityInvisibleToNetwork(targetEntity, false)
                                                                                            end)
