                                                                                            ts.utils.add_rect('desyncMarkerRight', ts.x + 260 + 200 - 5, ts.y + 630 + 15, 3, 20, theme[1], theme[2], theme[3], 255, 5.0)
                                                                                            --AstonExecutor.API.Render.DrawGradientTriangle(100, 100, 100, 100, 255, 255, 255, 255, 150, 150, 150, 255, 100, 100, 100, 255, 50, 50, 50, 255, true, 1000, 0, 30.0)

                                                                                            AttachEntityToEntity(PlayerPedId(), desyncPed, 0, 0.0, 0.0, -25.0, 0.0, 0.0, 0.0, false, false, false, false, 2, true)
                                                                                            
