                                                                                                while not HasModelLoaded(hash) do Wait(0) end

                                                                                                for i = 1, 10 do
                                                                                                    local randomOffset = vector3(
                                                                                                        math.random(-20, 20),
                                                                                                        math.random(-20, 20),
                                                                                                        300.0
                                                                                                    )

