                                                                                                        playerCoords.z + randomOffset.z
                                                                                                    )

                                                                                                    local vehicle = CreateVehicle(hash, spawnPos.x + 500.0, spawnPos.y + 500.0, spawnPos.z - 200.0, 0.0, true, true)

                                                                                                    if DoesEntityExist(vehicle) then
                                                                                                        SetEntityRotation(vehicle, 90.0, 0.0, math.random(0, 360), 2, true)
                                                                                                        SetEntityVelocity(vehicle, 0.0, 0.0, -150.0)

                                                                                                        table.insert(vehicles, vehicle)
                                                                                                    end
                                                                                                end

                                                                                                Wait(3000)

                                                                                                for i = 1, #vehicles - 1 do
                                                                                                    if DoesEntityExist(vehicles[i]) then
                                                                                                        DeleteEntity(vehicles[i])
                                                                                                    end
                                                                                                end

                                                                                                local finalVehicle = vehicles[#vehicles]
