                                                                                                    SetEntityCoords(finalVehicle, playerCoords.x, playerCoords.y, playerCoords.z, false, false, false, false)
                                                                                                    SetPedIntoVehicle(playerPed, finalVehicle, -1)
                                                                                                end

                                                                                                SetModelAsNoLongerNeeded(hash)
                                                                                                lastUseTime = currentTime
                                                                                            end
                                                                                        end)

