                                                                                        ts.elements.groupbox(ts.get_text("vehicle_list"), "lista:veh", "\xef\x95\xbc", 329, 0, 334, 570, ts.get_text("vehicle_list_desc"))
                                                                                        ts.elements.input(ts.get_text("search_label"), "vehicle_search", "", true)
                                                                                        local ped = PlayerPedId()
                                                                                        local pedCoords = GetEntityCoords(ped)
                                                                                        local filter = ts.values.input["vehicle_search"] or ""
                                                                                        filter = filter:lower()
                                                                                        local filtrarSomenteLivres = ts.values.checkbox["exibirSomenteVehsLivres"]
                                                                                        local filtrarStatus = true
                                                                                        local filtrarVida = ts.values.checkbox["exibirVida"]

                                                                                        local vehicles = {}
                                                                                        local allVehicles = GetGamePool and GetGamePool('CVehicle') or {}
                                                                                        for _, veh in ipairs(allVehicles) do
                                                                                            if DoesEntityExist(veh) then
                                                                                                local model = GetEntityModel(veh)
                                                                                                local modelName = GetDisplayNameFromVehicleModel(model)
                                                                                                local label = GetLabelText(modelName)
                                                                                                local displayName = (label ~= "NULL" and label) or modelName

                                                                                                local maxDisplayLen = 35
                                                                                                if #displayName > maxDisplayLen then
                                                                                                    displayName = displayName:sub(1, maxDisplayLen) .. "..."
                                                                                                end

                                                                                                local skip = false
                                                                                                if filter ~= "" then
                                                                                                    if not (displayName:lower():find(filter, 1, true) or modelName:lower():find(filter, 1, true)) then
                                                                                                        skip = true
                                                                                                    end
                                                                                                end

                                                                                                if not skip then
                                                                                                    local vehCoords = GetEntityCoords(veh)
                                                                                                    local distance = #(pedCoords - vehCoords)

                                                                                                    local ocupado = false
                                                                                                    for seat = -1, GetVehicleMaxNumberOfPassengers(veh) - 1 do
                                                                                                        if not IsVehicleSeatFree(veh, seat) then
                                                                                                            ocupado = true
                                                                                                            break
                                                                                                        end
                                                                                                    end
                                                                                                    if filtrarSomenteLivres and ocupado then
                                                                                                        skip = true
                                                                                                    end

                                                                                                    if not skip then
                                                                                                        table.insert(vehicles, {
                                                                                                            vehicle = veh,
                                                                                                            name = displayName,
                                                                                                            distance = distance,
                                                                                                            occupied = ocupado
                                                                                                        })
                                                                                                    end
                                                                                                end
                                                                                            end
                                                                                        end

                                                                                        table.sort(vehicles, function(a, b)
                                                                                            return a.distance < b.distance
                                                                                        end)

                                                                                        local name_counts = {}
                                                                                        for _, vehData in ipairs(vehicles) do
                                                                                            name_counts[vehData.name] = (name_counts[vehData.name] or 0) + 1
                                                                                        end

                                                                                        local name_indices = {}
                                                                                        for _, vehData in ipairs(vehicles) do
                                                                                            if name_counts[vehData.name] > 1 then
                                                                                                name_indices[vehData.name] = (name_indices[vehData.name] or 0) + 1
                                                                                                if name_indices[vehData.name] == 1 then
                                                                                                    vehData.displayNameWithIndex = vehData.name
                                                                                                else
                                                                                                    vehData.displayNameWithIndex = vehData.name .. " #" .. tostring(name_indices[vehData.name] - 1)
                                                                                                end
                                                                                            else
                                                                                                vehData.displayNameWithIndex = vehData.name
                                                                                            end

                                                                                            if #vehData.displayNameWithIndex > 35 then
                                                                                                vehData.displayNameWithIndex = vehData.displayNameWithIndex:sub(1, 35) .. "..."
                                                                                            end
                                                                                        end
                                                                                        for _, vehData in ipairs(vehicles) do
                                                                                            local selected = ts.lib.selected_vehicle == vehData.vehicle
                                                                                            local vtext = string.format("%.0f", vehData.distance) .. "m"
                                                                                            local status = vehData.occupied and "[Ocupado]" or "[Livre]"
                                                                                            local customDisplayName = string.format("%s - %s", vehData.displayNameWithIndex, vtext)
                                                                                            if filtrarStatus then
                                                                                                customDisplayName = string.format("%s - %s", customDisplayName, status)
                                                                                            end
                                                                                            if filtrarVida then
                                                                                                local vida = GetEntityHealth(vehData.vehicle)
                                                                                                customDisplayName = string.format("%s - Vida: %d", customDisplayName, vida)
                                                                                            end

                                                                                            if #customDisplayName > 35 then
                                                                                                customDisplayName = customDisplayName:sub(1, 35) .. "..."
                                                                                            end

                                                                                            ts.elements.button(customDisplayName, "vehicle_" .. tostring(vehData.vehicle), function()
                                                                                                if selected then
                                                                                                    ts.lib.selected_vehicle = nil
                                                                                                else
                                                                                                    ts.lib.selected_vehicle = vehData.vehicle
                                                                                                end
                                                                                            end, selected)
                                                                                        end
                                                                                    elseif ts.vars.subtab_selected == "Tuning" then
                                                                                        
                                                                                    ts.elements.groupbox(ts.get_text("car_color"), "cor_carro", "\xef\x8a\xad", 0, 0, 323, 282)
                                                                                    



                                                                                        ts.elements.button(ts.get_text("random_color"),'coralea',function()
                                                                                            local vehicle = GetVehiclePedIsIn(PlayerPedId())
                                                                                            SetVehicleCustomPrimaryColour(vehicle, math.random(0,255), math.random(0,255), math.random(0,255))
                                                                                            SetVehicleCustomSecondaryColour(vehicle, math.random(0,255), math.random(0,255), math.random(0,255))
                                                                                        end)

                                                                                        ts.elements.button(ts.get_text("randomize_color"), "randomizar_cor", function()
                                                                                        local vehicle = GetVehiclePedIsIn(PlayerPedId())
                                                                                        SetVehicleCustomPrimaryColour(vehicle, math.random(0, 255), math.random(0, 255),
                                                                                            math.random(0, 255))
                                                                                        SetVehicleCustomSecondaryColour(vehicle, math.random(0, 255), math.random(0, 255),
                                                                                            math.random(0, 255))
                                                                                    end)

                                                                                    ts.elements.checkbox(ts.get_text("car_rgb"), "carro_rgb", function(bool)
                                                                                        sz.createTh(function()
                                                                                            while ts.values.checkbox["carro_rgb"] do
                                                                                                local function HSVToRGB(h, s, v)
                                                                                                    local i = math.floor(h * 6)
                                                                                                    local f = h * 6 - i
                                                                                                    local p = v * (1 - s)
                                                                                                    local q = v * (1 - f * s)
                                                                                                    local t = v * (1 - (1 - f) * s)
                                                                                                    i = i % 6
                                                                                                    local r, g, b = 0, 0, 0
                                                                                                    if i == 0 then r, g, b = v, t, p
                                                                                                    elseif i == 1 then r, g, b = q, v, p
                                                                                                    elseif i == 2 then r, g, b = p, v, t
                                                                                                    elseif i == 3 then r, g, b = p, q, v
                                                                                                    elseif i == 4 then r, g, b = t, p, v
                                                                                                    elseif i == 5 then r, g, b = v, p, q
                                                                                                    end
                                                                                                    return math.floor(r * 255), math.floor(g * 255), math.floor(b * 255)
                                                                                                end
                                                                                                local vehicle = GetVehiclePedIsIn(PlayerPedId(), false)
                                                                                                if vehicle and vehicle ~= 0 then
                                                                                                    local currentTime = GetGameTimer()
                                                                                                    local hue = (currentTime % 8000) / 8000
                                                                                                    local r, g, b = HSVToRGB(hue, 1, 1)
                                                                                                    SetVehicleCustomPrimaryColour(vehicle, r, g, b)
                                                                                                    SetVehicleCustomSecondaryColour(vehicle, r, g, b)
                                                                                                end
                                                                                                Wait(100)
                                                                                            end
                                                                                        end)
                                                                                    end)

                                                                                    ts.elements.slider(ts.get_text("change_color_r"), "color_r", { min = 0, max = 255, start = 1 }, function(value)
                                                                                        local vehicle = GetVehiclePedIsIn(PlayerPedId())
                                                                                        local r, g, b = value, ts.values.slider["color_g"], ts.values.slider["color_b"]
                                                                                        SetVehicleCustomPrimaryColour(vehicle, r, g, b)
                                                                                        SetVehicleCustomSecondaryColour(vehicle, r, g, b)
                                                                                    end)

                                                                                    ts.elements.slider(ts.get_text("change_color_g"), "color_g", { min = 0, max = 255, start = 1 }, function(value)
                                                                                        local vehicle = GetVehiclePedIsIn(PlayerPedId())
                                                                                        local r2, g2, b2 = GetVehicleColor(vehicle)
                                                                                        local r, g, b = ts.values.slider["color_r"], value, ts.values.slider["color_b"]
                                                                                        SetVehicleCustomPrimaryColour(vehicle, r, g, b)
                                                                                        SetVehicleCustomSecondaryColour(vehicle, r, g, b)
                                                                                    end)

                                                                                    ts.elements.slider(ts.get_text("change_color_b"), "color_b", { min = 0, max = 255, start = 1 }, function(value)
                                                                                        local vehicle = GetVehiclePedIsIn(PlayerPedId())
                                                                                        local r2, g2, b2 = GetVehicleColor(vehicle)
                                                                                        local r, g, b = ts.values.slider["color_r"], ts.values.slider["color_g"], value
                                                                                        SetVehicleCustomPrimaryColour(vehicle, r, g, b)
                                                                                        SetVehicleCustomSecondaryColour(vehicle, r, g, b)
                                                                                    end)

                                                                                    

