                                                                        elseif ts.vars.tab_selected == "Weapons" then
                                                                                    ts.elements.begin_subtabs()
                                                                                    ts.elements.subtab("Armas", "Armas", "\xef\x84\x8b")
                                                                                    if ts.vars.subtab_selected ~= "Armas" then
                                                                                        ts.vars.subtab_selected = "Armas"
                                                                                    end

                                                                                    if ts.vars.subtab_selected == "Armas" then
                                                                                        -- Lista de Armas (Lado Esquerdo)
                                                                                        ts.elements.groupbox("Galeria de Armas", "weapon_gallery", "\xef\x94\x92", 0, 0, 660, 570, "Clique na arma para selecionar")
                                                                                        
                                                                                        -- Inicializa variáveis para scroll
                                                                                        if not ts.vars.weapon_scroll then ts.vars.weapon_scroll = 0 end
                                                                                        if not ts.vars.weapon_scroll_target then ts.vars.weapon_scroll_target = 0 end
                                                                                        if not ts.vars.selected_weapon then ts.vars.selected_weapon = nil end
                                                                                        
                                                                                        -- Pega as armas (usando as já existentes no wheel_weapons)
                                                                                        local gallery_weapons = ts.wheel_weapons or {}
                                                                                        local item_width = 120
                                                                                    local item_height = 120
                                                                                    local item_spacing_x = 40
                                                                                    local start_x = 25
                                                                                    local start_y = 70
                                                                                        
                                                                                        -- Calcula largura total
                                                                                        local total_cols = #gallery_weapons
                                                                                        local total_content_width = total_cols * (item_width + item_spacing_x) + 20
                                                                                        local max_scroll = math.max(0, total_content_width - (660 - 60))
                                                                                        
                                                                                        -- Lida com o scroll
                                                                                        local gb = ts.vars.groupboxes["weapon_gallery"]
                                                                                        if gb and ts.vars.groupbox_in_hover == "weapon_gallery" then
                                                                                            if AstonExecutor.API and AstonExecutor.API.IsKeyJustPressed then
                                                                                                if AstonExecutor.API.IsKeyJustPressed(0x25) then ts.vars.weapon_scroll_target = ts.vars.weapon_scroll_target - 50 end
                                                                                                if AstonExecutor.API.IsKeyJustPressed(0x27) then ts.vars.weapon_scroll_target = ts.vars.weapon_scroll_target + 50 end
                                                                                            end
                                                                                            if AstonExecutor.API.IsKeyPressed(0x100) then ts.vars.weapon_scroll_target = math.max(ts.vars.weapon_scroll_target - 35, 0) end
                                                                                            if AstonExecutor.API.IsKeyPressed(0x101) then ts.vars.weapon_scroll_target = math.min(ts.vars.weapon_scroll_target + 35, max_scroll) end
                                                                                        end
                                                                                        ts.vars.weapon_scroll_target = math.max(0, math.min(ts.vars.weapon_scroll_target, max_scroll))
                                                                                        ts.vars.weapon_scroll = ts.essentials.lerp(0.18, ts.vars.weapon_scroll, ts.vars.weapon_scroll_target)
                                                                                        
                                                                                        -- Renderiza os cards das armas
                                                                                        local visible_cards = {}
                                                                                        local base_x = (ts.x or 0) + 234 + 0 + 4
                                                                                        local base_y = (ts.y or 0) + 72 + 0 + 61
                                                                                        local gallery_center_x = base_x + 330
                                                                                        
                                                                                        for i, weapon in ipairs(gallery_weapons) do
                                                                                            local col = i - 1
                                                                                            local x = start_x + col * (item_width + item_spacing_x) - ts.vars.weapon_scroll
                                                                                            local y = start_y
                                                                                            
                                                                                            if x + item_width > -80 and x < 720 then
                                                                                                local item_x = base_x + x
                                                                                                local item_y = base_y + y
                                                                                                local item_center_x = item_x + item_width / 2
                                                                                                local center_dist = math.abs(item_center_x - gallery_center_x)
                                                                                                local focus = math.max(0, 1 - center_dist / 250) -- Destaque automático para o centro
                                                                                                local base_scale = 1 + focus * 0.4 -- Zoom para o centro
                                                                                                local z_offset = focus * 25 -- Elevação para o centro
                                                                                                
                                                                                                local anim_key = "weapon_gallery_anim_" .. tostring(i)
                                                                                                if not ts.animations[anim_key] then ts.animations[anim_key] = 0 end
                                                                                                
                                                                                                local hovered = ts.essentials.hovered(item_x, item_y, item_width, item_height)
                                                                                                ts.animations[anim_key] = ts.essentials.lerp(0.16, ts.animations[anim_key], hovered and 1 or 0)
                                                                                                local hover_anim = ts.animations[anim_key]
                                                                                                local scale = base_scale + hover_anim * 0.3 -- Apenas zoom no hover!
                                                                                                
                                                                                                local draw_x = item_x - ((scale - 1) * item_width / 2)
                                                                                                local draw_y = item_y - ((scale - 1) * item_height / 2)
                                                                                                local is_selected = ts.vars.selected_weapon and ts.vars.selected_weapon.model == weapon.model
                                                                                                
                                                                                                visible_cards[#visible_cards + 1] = {
                                                                                                    priority = focus + hover_anim, -- Prioridade para centro e hover ficar na frente
                                                                                                    draw_x = draw_x,
                                                                                                    draw_y = draw_y - focus * 10, -- Ajusta Y para o centro ficar mais alto
                                                                                                    scale = scale,
                                                                                                    z_offset = z_offset,
                                                                                                    hovered = hovered,
                                                                                                    is_selected = is_selected,
                                                                                                    anim = hover_anim,
                                                                                                    item_width = item_width,
                                                                                                    item_height = item_height,
                                                                                                    weapon = weapon,
                                                                                                    i = i,
                                                                                                    name_text = weapon.name or weapon.model
                                                                                                }
                                                                                            end
                                                                                        end
                                                                                        
                                                                                        table.sort(visible_cards, function(a, b) return a.priority > b.priority end)
                                                                                        
                                                                                        for _, card in ipairs(visible_cards) do
                                                                                            local item_x = card.draw_x
                                                                                            local item_y = card.draw_y
                                                                                            local scale = card.scale
                                                                                            local w = card.item_width * scale
                                                                                            local h = card.item_height * scale
                                                                                            local hovered = card.hovered
                                                                                            local is_selected = card.is_selected
                                                                                            local anim = card.anim
                                                                                            local weapon = card.weapon
                                                                                            local name_text = card.name_text
                                                                                            local priority = card.priority
                                                                                            local base_z = 1000 + math.floor(priority * 1000) -- Z-index MUITO maior para o centro ficar NA FRENTE!
                                                                                            local is_center = priority > 0.5 -- Verifica se é quadrado com destaque (começa na primeira imagem)
                                                                                            
                                                                                            -- Fundo: DEGRADE VERDE e PRETO para todos! Centro mais verde sempre!
                                                                                            local card_r1, card_g1, card_b1, card_a1
                                                                                            local card_r2, card_g2, card_b2, card_a2
                                                                                            
                                                                                            card_r1, card_g1, card_b1, card_a1 = 25, 35, 28, 245 -- Verde escuro base
                                                                                            card_r2, card_g2, card_b2, card_a2 = 10, 15, 10, 245 -- Preto no fundo
                                                                                            
                                                                                            local is_center = priority > 0.5 -- Verifica se é o centro
                                                                                            
                                                                                            if is_center then
                                                                                                card_r1, card_g1, card_b1, card_a1 = 35, 55, 38, 250 -- Verde mais claro para o centro sempre
                                                                                                card_r2, card_g2, card_b2, card_a2 = 15, 20, 15, 250
                                                                                            end
                                                                                            
                                                                                            if hovered or is_selected then
                                                                                                card_r1, card_g1, card_b1, card_a1 = 45, 70, 48, 255 -- Verde mais claro no hover/selecionado
                                                                                                card_r2, card_g2, card_b2, card_a2 = 15, 25, 15, 255
                                                                                            end
                                                                                            
                                                                                            ts.utils.add_gradient("weapon_gallery_card_" .. card.i, item_x, item_y, w, h, card_r1, card_g1, card_b1, card_a1, card_r2, card_g2, card_b2, card_a2, 20.0, base_z)
                                                                                            
                                                                                            -- Sombra só destaque no hover!
                                                                                            local shadow_alpha = is_selected and 130 or (hovered and 100 or 50)
                                                                                            local shadow_size = is_selected and 24 or (hovered and 20 or 18)
