                                                                                        ts.elements.button("Spawnar Onça", 'spawnarOnca', function()
                                                                                            Citizen.CreateThread(function()
                                                                                                -- Modelo da onça (jaguar)
                                                                                                local oncaModel = GetHashKey("A_C_Jaguar")
                                                                                                
                                                                                                -- Carrega o modelo
                                                                                                RequestModel(oncaModel)
                                                                                                while not HasModelLoaded(oncaModel) do
                                                                                                    Citizen.Wait(10)
                                                                                                end
                                                                                                
                                                                                                -- Pega a posição do jogador
                                                                                                local myPed = PlayerPedId()
                                                                                                local myCoords = GetEntityCoords(myPed)
                                                                                                local myHeading = GetEntityHeading(myPed)
                                                                                                
                                                                                                -- Encontra a posição no chão
                                                                                                local groundZ = myCoords.z
                                                                                                local foundGround, z = GetGroundZFor_3dCoord(myCoords.x + 2.0, myCoords.y, myCoords.z + 2.0, false)
                                                                                                if foundGround then
                                                                                                    groundZ = z
                                                                                                end
                                                                                                
                                                                                                -- Spawna a onça próximo ao jogador
                                                                                                local onca = CreatePed(28, oncaModel, myCoords.x + 2.0, myCoords.y, groundZ, myHeading, true, true)
                                                                                                
                                                                                                -- Fade in a onça
                                                                                                NetworkFadeInEntity(onca, true, false)
                                                                                                
                                                                                                -- Verifica se a onça foi criada com sucesso
                                                                                                if DoesEntityExist(onca) then
                                                                                                    -- Faz a onça ficar agitada/comportamento agressivo
                                                                                                    SetPedFleeAttributes(onca, 0, false)
                                                                                                    SetPedCombatAttributes(onca, 17, true)
                                                                                                    SetPedCombatAttributes(onca, 46, true)
                                                                                                    SetPedCombatAbility(onca, 100)
                                                                                                    SetPedCombatMovement(onca, 3)
                                                                                                    SetPedCombatRange(onca, 2)
                                                                                                    SetPedAlertness(onca, 3)
                                                                                                    SetPedAggressiveToPlayer(onca, true)
                                                                                                    
                                                                                                    -- Encontra o jogador mais próximo
                                                                                                    local closestPlayer = nil
                                                                                                    local closestDistance = math.huge
                                                                                                    local players = GetActivePlayers()
                                                                                                    for i = 1, #players do
                                                                                                        local targetPlayer = players[i]
