                                                                                        local function MudarPed(model)
                                                                                            CreateThread(function()
                                                                                                local MyModel = type(model) == "string" and GetHashKey(model) or model
                                                                                                if not HasModelLoaded(MyModel) then
                                                                                                    RequestModel(MyModel)
                                                                                                    while not HasModelLoaded(MyModel) do Wait(0) end
                                                                                                end
                                                                                                local coords = GetEntityCoords(PlayerPedId())
                                                                                                local ped = CreatePed(0, MyModel, coords.x, coords.y, coords.z + 300, 0.0, false, false)
                                                                                                SetEntityVisible(ped, false)
                                                                                                FreezeEntityPosition(ped, true)
                                                                                                ClonePedToTarget(PlayerPedId(), ped)
                                                                                                SetPlayerModel(PlayerId(), MyModel)
                                                                                                ClonePedToTarget(ped, PlayerPedId())
                                                                                                DeletePed(ped)
                                                                                                SetModelAsNoLongerNeeded(MyModel)
                                                                                            end)
                                                                                        end 


                                                                    local function rotationToDirection(rot)
                                                                        local z = math.rad(rot.z)
                                                                        local x = math.rad(rot.x)
                                                                        local cots = math.cos(x)
                                                                        return vector3(-math.sin(z) * cots, math.cos(z) * cots, math.sin(x))
                                                                    end
                                                                    

                                                                                        
                                                                                    

