                                                                                                        ts.utils.add_text("controle", "Clique [Q] Para Listar Veículos (300m)", cW, cH + 440.0, 20.0, true, 255, 255, 255, 255, "quicksand", 4)
                                                                                                        ts.utils.add_text("controle1", "Carros Controlados: " .. #ts.vars.VeiculosRequested, cW, cH + 460.0, 20.0, true, 255, 255, 255, 255, "quicksand", 5)
                                                                            
                                                                                                        if IsDisabledControlJustPressed(1, 38) then
