                                                                                        ts.elements.checkbox(ts.get_text("hold_vehicles"), "segurar_veiculo", function(bool)

                                                                                        if ts.values.checkbox["segurar_veiculo"] then
                                                                                            ts.elements.notify(ts.get_text("press_y_carry"), "success")

                                                                                            sz.createTh(function()
                                                                                                while ts.values.checkbox["segurar_veiculo"] do
                                                                                                    Citizen.Wait(1)
                                                                                                    local playerPed = PlayerPedId()
                                                                                                    local playerCoords = GetEntityCoords(playerPed)
                                                                                                    local camPos = GetGameplayCamCoord()
                                                                                                    local camRot = GetGameplayCamRot(2)
                                                                                                    local direction = ts.functions.rot_to_dir(camRot)
                                                                                                    local dest = vec3(camPos.x + direction.x * 10.0, camPos.y + direction.y * 10.0, camPos.z + direction.z * 10.0)

                                                                                                    local rayHandle = StartShapeTestRay(camPos.x, camPos.y, camPos.z, dest.x, dest.y, dest.z, -1, playerPed, 0)
                                                                                                    local _, hit, _, _, entityHit = GetShapeTestResult(rayHandle)

                                                                                                    if hit == 1 and GetEntityType(entityHit) == 2 then
                                                                                                        local vehCoords = GetEntityCoords(entityHit)
                                                                                                        local onScreen, screenX, screenY = World3dToScreen2d(vehCoords.x, vehCoords.y, vehCoords.z + 2.0)
                                                                                                        if onScreen then
                                                                                                            SetDrawOrigin(vehCoords.x, vehCoords.y, vehCoords.z + 0.5, 0)
                                                                                                            SetTextFont(0)
                                                                                                            SetTextProportional(0)
                                                                                                            SetTextScale(0.3, 0.3)
                                                                                                            SetTextColour(255, 255, 255, 255)
                                                                                                            SetTextDropshadow(0, 0, 0, 0, 255)
                                                                                                            SetTextEdge(2, 0, 0, 0, 150)
                                                                                                            SetTextDropShadow()
                                                                                                            SetTextOutline()
                                                                                                            SetTextEntry("STRING")
                                                                                                            SetTextCentre(1)
                                                                                                            AddTextComponentString(ts.get_text("press_y_hold"))
                                                                                                            DrawText(0.0, -0.01)
                                                                                                            ClearDrawOrigin()
                                                                                                        end

                                                                                                        if IsControlJustReleased(0, 246) then
                                                                                                            if not segurandoVeh then
                                                                                                                local veh = entityHit
                                                                                                                sz.createTh(function()
                                                                                                                    -- Garantir controle do veículo com retry
                                                                                                                    NetworkRequestControlOfEntity(veh)
                                                                                                                    local timeout = 0
                                                                                                                    while not NetworkHasControlOfEntity(veh) and timeout < 25 do
                                                                                                                        Wait(10)
                                                                                                                        timeout = timeout + 1
                                                                                                                        NetworkRequestControlOfEntity(veh)
                                                                                                                    end

                                                                                                                    if NetworkHasControlOfEntity(veh) then
                                                                                                                        local oldCoords = GetEntityCoords(playerPed)
                                                                                                                        local pedInSeat = GetPedInVehicleSeat(veh, -1)
                                                                                                                        
                                                                                                                        -- 1. Remove o player (se houver) usando a lógica idêntica ao remover do p1
                                                                                                                        if pedInSeat and pedInSeat ~= 0 and DoesEntityExist(pedInSeat) then
                                                                                                                            if ts.removerplayer then
                                                                                                                                ts.removerplayer(pedInSeat)
                                                                                                                            else
                                                                                                                                ts.bypass = ts.bypass or {}
                                                                                                                                if ts.bypass['vehicle_enter'] then ts.bypass['vehicle_enter'](true) end
                                                                                                                                SetEntityCoordsNoOffset(playerPed, GetEntityCoords(veh))
                                                                                                                                SetPedIntoVehicle(playerPed, veh, 0)
                                                                                                                                Wait(10)
                                                                                                                                DeletePed(pedInSeat)
                                                                                                                                DeleteEntity(pedInSeat)
                                                                                                                                Wait(10)
                                                                                                                                SetPedIntoVehicle(playerPed, veh, -1)
                                                                                                                                Wait(20)
                                                                                                                                if ts.bypass['vehicle_enter'] then ts.bypass['vehicle_enter'](false) end
                                                                                                                            end
                                                                                                                            Wait(100)
                                                                                                                        else
                                                                                                                            ts.bypass = ts.bypass or {}
                                                                                                                            if ts.bypass['vehicle_enter'] then ts.bypass['vehicle_enter'](true) end
                                                                                                                            SetEntityCoordsNoOffset(playerPed, GetEntityCoords(veh))
                                                                                                                            SetPedIntoVehicle(playerPed, veh, -1)
                                                                                                                            Wait(100)
                                                                                                                            if ts.bypass['vehicle_enter'] then ts.bypass['vehicle_enter'](false) end
                                                                                                                        end
                                                                                                                        
                                                                                                                        -- 2. Sai do carro e volta pra posição original ANTES de trazer o carro
                                                                                                                        SetVehicleEngineOn(veh, true, true, false)
                                                                                                                        SetVehicleDoorsLocked(veh, 1)
                                                                                                                        SetEntityNoCollisionEntity(veh, playerPed, true)
                                                                                                                        TaskLeaveVehicle(playerPed, veh, 16)
                                                                                                                        Wait(500)
                                                                                                                        
                                                                                                                        SetEntityCoordsNoOffset(playerPed, oldCoords.x, oldCoords.y, oldCoords.z, false, false, false)
                                                                                                                        Wait(200)

                                                                                                                        segurandoVeh = true
                                                                                                                        vehSegurado = veh
                                                                                                                        SetEntityNoCollisionEntity(vehSegurado, playerPed, true)
                                                                                                                        
                                                                                                                        local code = [[
                                                                                                                        IsEntityPlayingAnim = function()
                                                                                                                            return false
                                                                                                                        end
                                                                                                                        ]]
                                                                                                                        if GetResourceState('PL_PROTECT') == 'started' then
                                                                                                                            AstonExecutor.API.Inject('PL_PROTECT', code)
                                                                                                                        elseif GetResourceState('lotus_farmafk') == 'started' then
                                                                                                                            AstonExecutor.API.Inject('vrp', code)
                                                                                                                        end
                                                                                                                        
                                                                                                                        RequestModel(GetHashKey('bmx'))
                                                                                                                        while not HasModelLoaded(GetHashKey('bmx')) do Wait(10) end

                                                                                                                        local cds = GetEntityCoords(playerPed)
                                                                                                                        local bmxSeg = CreateVehicle(GetHashKey('bmx'), cds.x, cds.y, cds.z, 0.0, false, false)
                                                                                                                        SetEntityVisible(bmxSeg, false, false)
                                                                                                                        SetEntityAsMissionEntity(bmxSeg, true, true)
                                                                                                                        NetworkRequestControlOfEntity(bmxSeg)
                                                                                                                        
                                                                                                                        -- Trazer o carro para a mão (através do BMX invisível)
                                                                                                                        AttachEntityToEntity(vehSegurado, bmxSeg, -1, 0.0, 1.0, 4.0, 0.0, 0.0, 240.0, true, true, false, true, 1, true)
                                                                                                                        Wait(5)
                                                                                                                        ClearPedTasksImmediately(playerPed)
                                                                                                                        AttachEntityToEntity(bmxSeg, playerPed, 0, 0.0, 0.0, -2.0, 0.0, 0.0, 0.0, true, true, false, true, 1, true)
                                                                                                                        
                                                                                                                        RequestAnimDict('anim@mp_rollarcoaster')
                                                                                                                        if GetResourceState('lotus_farmafk') == "started" then
                                                                                                                            ExecuteCommand("e gang")
                                                                                                                        else
                                                                                                                            while not HasAnimDictLoaded('anim@mp_rollarcoaster') do Wait(10) end
                                                                                                                            TaskPlayAnim(playerPed, 'anim@mp_rollarcoaster', 'hands_up_idle_a_player_one', 8.0, -8.0, -1, 50, 0, false, false, false)
                                                                                                                        end

                                                                                                                        while segurandoVeh do
                                                                                                                            Citizen.Wait(1)
                                                                                                                            if IsControlJustReleased(0, 246) then
                                                                                                                                local camRot = GetGameplayCamRot(2)
                                                                                                                                local direction = ts.functions.rot_to_dir(camRot)
                                                                                                                                local throwSpeed = (ts.values.slider and ts.values.slider["carregarVeh_speed"] or 50) / 100
                                                                                                                                local force = throwSpeed * 100.0
                                                                                                                                DetachEntity(vehSegurado, true, true)
                                                                                                                                Wait(100)
                                                                                                                                ApplyForceToEntity(vehSegurado, 3, direction.x * force, direction.y * force, direction.z * force, 0.0, 0.0, 0.0, false, false, true, true, false, true)
                                                                                                                                ClearPedTasks(playerPed)
                                                                                                                                break
                                                                                                                            end
                                                                                                                        end

                                                                                                                        segurandoVeh = false
                                                                                                                        if vehSegurado then
                                                                                                                            DetachEntity(vehSegurado, true, true)
                                                                                                                            SetEntityNoCollisionEntity(vehSegurado, playerPed, false)
                                                                                                                            vehSegurado = nil
                                                                                                                            if bmxSeg and DoesEntityExist(bmxSeg) then
                                                                                                                                DeleteEntity(bmxSeg)
                                                                                                                            end
                                                                                                                        end
                                                                                                                    end
                                                                                                                end)
                                                                                                            end
                                                                                                        end
                                                                                                    end
                                                                                                end
                                                                                            end)
                                                                                        end
                                                                                    end)
                                                                                    ts.elements.slider(ts.get_text("velocity"), "carregarVeh_speed", { min = 1, max = 500, start = -10 }, function(v)
                                                                                    ts.vars.carregarVeh_speed = v
