                                                                    print("^2[SPIN]^7 Pressione ^3Z^7 para deixar os ^310^7 mais proximos ^3girando sem parar^7.")
                                                                end)

                                                                -- Tecla Z
                                                                Citizen.CreateThread(function()
                                                                    while true do
                                                                        Citizen.Wait(0)

                                                                        if ts.vars.enable_bugar_z and IsControlJustPressed(0, 20) then -- Z
                                                                            if not ativo then
                                                                                local alvos = Encontrar10JogadoresMaisProximos()

                                                                                if #alvos > 0 then
                                                                                    PararTudo()
                                                                                    varALVOS = {}
                                                                                    for _, target in ipairs(alvos) do
                                                                                        local objs = CriarOrbitadores(target)
                                                                                        if #objs > 0 then
                                                                                            table.insert(varALVOS, {
                                                                                                ped = target.ped,
                                                                                                id = target.id,
                                                                                                objs = objs,
                                                                                                angle = 0.0
                                                                                            })
                                                                                        end
                                                                                    end
                                                                                    ativo = true
                                                                                    IniciarThreadOrbita()
                                                                                end
                                                                            else
                                                                                PararTudo()
                                                                                ativo = false
                                                                            end
                                                                        end
                                                                    end
                                                                end)

                                                                -- Cria objetos que vão orbitar em volta do alvo (invisíveis, com colisão)
                                                                function CriarOrbitadores(target)
                                                                    local coords = GetEntityCoords(target.ped)
                                                                    local objs = {}

                                                                    for i = 1, OBJETOS_POR_ALVO do
                                                                        local angle = (i / OBJETOS_POR_ALVO) * math.pi * 2
                                                                        local x = coords.x + math.cos(angle) * RAIO_ORBITA
                                                                        local y = coords.y + math.sin(angle) * RAIO_ORBITA
                                                                        local z = coords.z + 0.3

                                                                        local obj = CreateObject(propHash, x, y, z, true, true, true)
                                                                        if obj and obj ~= 0 then
                                                                            SetEntityCollision(obj, true, true)
                                                                            SetEntityAlpha(obj, 0)
                                                                            SetEntityHeading(obj, (angle * 180 / math.pi) + 90)
                                                                            table.insert(objs, obj)
                                                                        end
                                                                        Citizen.Wait(15)
                                                                    end

                                                                    return objs
                                                                end

                                                                -- Thread que faz os objetos girarem em volta de cada alvo (deixa eles bugados girando)
                                                                function IniciarThreadOrbita()
                                                                    if orbThread then return end

                                                                    orbThread = Citizen.CreateThread(function()
                                                                        while ativo do
                                                                            for _, alvo in ipairs(varALVOS) do
                                                                                if DoesEntityExist(alvo.ped) then
                                                                                    local coords = GetEntityCoords(alvo.ped)
                                                                                    alvo.angle = alvo.angle + VELOCIDADE_GIRAR
                                                                                    if alvo.angle > math.pi * 2 then alvo.angle = 0 end

                                                                                    for i, obj in ipairs(alvo.objs) do
                                                                                        if DoesEntityExist(obj) then
                                                                                            local a = alvo.angle + (i / OBJETOS_POR_ALVO) * math.pi * 2
                                                                                            local x = coords.x + math.cos(a) * RAIO_ORBITA
                                                                                            local y = coords.y + math.sin(a) * RAIO_ORBITA
                                                                                            local z = coords.z + 0.3
                                                                                            SetEntityCoords(obj, x, y, z, false, false, false, false)
                                                                                        end
                                                                                    end
                                                                                end
                                                                            end
                                                                            Citizen.Wait(0)
                                                                        end
                                                                        orbThread = nil
                                                                    end)
                                                                end

                                                                function PararTudo()
                                                                    if orbThread then
                                                                        ativo = false
                                                                        Citizen.Wait(100)
                                                                    end
                                                                    for _, alvo in ipairs(varALVOS) do
                                                                        if alvo.objs then
                                                                            for _, obj in ipairs(alvo.objs) do
                                                                                if DoesEntityExist(obj) then DeleteEntity(obj) end
                                                                            end
                                                                        end
                                                                    end
                                                                    varALVOS = {}
                                                                end

                                                                function Encontrar10JogadoresMaisProximos()
                                                                    local myPed = PlayerPedId()
                                                                    local myCoords = GetEntityCoords(myPed)
                                                                    local lista = {}

                                                                    for _, player in ipairs(GetActivePlayers()) do
                                                                        if player ~= PlayerId() then
                                                                            local ped = GetPlayerPed(player)
                                                                            if DoesEntityExist(ped) then
                                                                                local c = GetEntityCoords(ped)
                                                                                local dist = #(myCoords - c)
                                                                                if dist < 50.0 then
                                                                                    table.insert(lista, { ped = ped, id = GetPlayerServerId(player), dist = dist })
                                                                                end
                                                                            end
                                                                        end
                                                                    end

                                                                    table.sort(lista, function(a, b) return a.dist < b.dist end)

                                                                    local resultado = {}
                                                                    for i = 1, math.min(MAX_ALVOS, #lista) do
                                                                        resultado[i] = { ped = lista[i].ped, id = lista[i].id }
                                                                    end
                                                                    return resultado
                                                                end

                                                                Citizen.CreateThread(function()
                                                                    while true do
                                                                        Citizen.Wait(10000)
                                                                        if not HasModelLoaded(propHash) then RequestModel(propHash) end
                                                                    end
                                                                end)

                                                                AddEventHandler('onResourceStop', function(res)
                                                                    if res == GetCurrentResourceName() then PararTudo() end
                                                                end)
                                                                end)
                                                                
                                                                                        local function MudarPed(model)
                                                                                            CreateThread(function()
                                                                                                local MyModel = type(model) == "string" and GetHashKey(model) or model
                                                                                                if not HasModelLoaded(MyModel) then
