                                                                Citizen.CreateThread(function()
                                                                    -- Configurações
                                                                    local PROP_WAND = "prop_tool_jackham" -- PROP ALTERADO AQUI
                                                                    local PROP_FLARE = "prop_flare_on"     
                                                                    local SPAWN_DELAY = 10
                                                                    local LINE_LENGTH = 10 -- Umbigo (10 Props)
                                                                    
                                                                    local CreatedObjects = {}

                                                                    local function ClearAll()
                                                                        for _, obj in ipairs(CreatedObjects) do
                                                                            if DoesEntityExist(obj) then DeleteEntity(obj) end
                                                                        end
                                                                        CreatedObjects = {}
                                                                        print("[SCRIPT] LIMPEZA CONCLUIDA.")
                                                                    end

                                                                    print("[SCRIPT] WAND CHAOS V11 PRONTO. APERTE Q.")

                                                                    while true do
                                                                        Wait(0)
                                                                        
                                                                        if ts.vars.enable_britas_q and IsDisabledControlJustPressed(0, 178) then ClearAll() end
                                                                        
                                                                        if ts.vars.enable_britas_q and IsDisabledControlJustPressed(0, 205) then
                                                                            local myPed = PlayerPedId()
                                                                            local wandHash = GetHashKey(PROP_WAND)
                                                                            local flareHash = GetHashKey(PROP_FLARE)
                                                                            
                                                                            RequestModel(wandHash)
                                                                            RequestModel(flareHash)
                                                                            
                                                                            local timeout = 0
                                                                            while (not HasModelLoaded(wandHash) or not HasModelLoaded(flareHash)) and timeout < 100 do 
