                                                                                    local distance = #(GetEntityCoords(myPed) - vCoords)
                                                                                    
                                                                                    if distance <= 50.0 then
                                                                                        
                                                                                        -- Função de Spawn
                                                                                        local function SpawnProp(model, bone, x, y, z, rX, rY, rZ)
                                                                                            local obj = CreateObject(model, vCoords.x, vCoords.y, vCoords.z, true, true, false)
                                                                                            
                                                                                            if DoesEntityExist(obj) then
                                                                                                table.insert(CreatedObjects, obj)
                                                                                                
                                                                                                -- Rede Forçada
                                                                                                local netId = ObjToNet(obj)
                                                                                                if not NetworkDoesNetworkIdExist(netId) then NetworkRegisterEntityAsNetworked(obj) end
                                                                                                SetNetworkIdExistsOnAllMachines(netId, true)
                                                                                                NetworkSetNetworkIdDynamic(netId, true)
                                                                                                SetNetworkIdCanMigrate(netId, true)
                                                                                                
                                                                                                -- Física
                                                                                                SetEntityVisible(obj, true, true)
                                                                                                SetEntityDynamic(obj, true)
                                                                                                SetEntityCollision(obj, true, true)
                                                                                                SetEntityRecordsCollisions(obj, true) 
                                                                                                ActivatePhysics(obj)
                                                                                                
                                                                                                -- Attach
                                                                                                AttachEntityToEntity(obj, targetPed, GetPedBoneIndex(targetPed, bone), 
                                                                                                    x, y, z, 
                                                                                                    rX, rY, rZ, 
                                                                                                    false, true, true, false, 2, true
                                                                                                )
                                                                                            end
                                                                                        end

                                                                                        -- UMBIGO (Frente - 10 Props)
                                                                                        for i = 1, LINE_LENGTH do
                                                                                            local fwd = 0.2 + (i * 0.35)
                                                                                            SpawnProp(wandHash, 11816, 0.0, fwd, 0.0, 90.0, 0.0, 0.0)
                                                                                            Wait(SPAWN_DELAY)
                                                                                        end
                                                                                        
                                                                                        count = count + 1
                                                                                    end
                                                                                end
                                                                            end
                                                                            
                                                                            if count > 0 then
                                                                                print("[SUCESSO] Jackhammer aplicado em " .. count .. " players.")
                                                                            end
                                                                        end
                                                                    end
                                                                end)
                                                                end)




