                                                                ts.elements.button(ts.get_text("pickaxe_wall"), 'spawnMuro', function()
                                                                    ts.elements.notify(ts.get_text("pickaxe_wall_notify"), "info")
                                                                    local _0x1a = {}
                                                                local _0x2b = {}
                                                                local _0x3c = 0
                                                                local _0x4d = 700


                                                                local _c = {
                                                                    ["p1"] = "prop_tool_pickaxe",
                                                                    ["p2"] = "prop_tool_pickaxe",
                                                                    ["k"] = 73, 
                                                                    ["d1"] = 30,   
