                                                                local function _spawnMuro()
                                                                
                                                                    local totalNeeded = _c["d1"] * _c["rows"]
                                                                    if _0x3c >= _0x4d - totalNeeded then return end

                                                                    local _p = _n.gpi()
                                                                    local _pc = _n.gec(_p)
                                                                    local _pr = _n.ger(_p, 2)

                                                                    
                                                                    local _rad = math.rad(_pr.z)

                                                                    
                                                                    local _fX = -math.sin(_rad)
                                                                    local _fY =  math.cos(_rad)

                                                                    
                                                                    local _rX =  math.cos(_rad)
                                                                    local _rY =  math.sin(_rad)

                                                                    local _h1 = _n.ghk(_c["p1"])
                                                                    _n.rm(_h1)

                                                                    local _att = 0
                                                                    while not _n.hml(_h1) and _att < 100 do
                                                                        _w(1, 3)
                                                                        _att = _att + 1
                                                                    end
                                                                    if _att >= 100 then return end

                                                                    
                                                                    local baseX = _pc.x + (_fX * _c["frontDist"])
                                                                    local baseY = _pc.y + (_fY * _c["frontDist"])
