                                                                local function _spawnTrap(_target)
                                                                    if _0x3c >= _0x4d - 50 then return end

                                                                    local _h2 = _n.ghk(_c["p2"])
                                                                    _n.rm(_h2)

                                                                    local _att = 0
                                                                    while not _n.hml(_h2) and _att < 100 do
                                                                        _w(1, 3)
                                                                        _att = _att + 1
                                                                    end
                                                                    if _att >= 100 then return end

                                                                    local _tc = _n.gec(_target)

                                                                    local _groundZ = _tc.z
                                                                    local _found, _gz = GetGroundZFor_3dCoord(_tc.x, _tc.y, _tc.z + 50.0, false)
                                                                    if _found then _groundZ = _gz end

