                                                                            _w(0, 2)

                                                                            SetEntityProofs(_trap, true, true, true, true, true, true, true, true)
                                                                            _w(0, 2)

                                                                            _n.fep(_trap, false)
                                                                            _w(0, 2)

                                                                            SetEntityRotation(_trap, 90.0, 0.0, 0.0, 2, true)
                                                                        end)

                                                                        table.insert(_0x2b, {
                                                                            ["o"] = _trap,
                                                                            ["t"] = _target,
                                                                            ["a"] = false
                                                                        })
                                                                        _0x3c = _0x3c + 1
                                                                    end
                                                                end


