                                                                                        -- Auto Farm (Teleport)
                                                                                        ts.elements.checkbox("Auto Farm", "autoFarm", function(state)
                                                                                            if ts.values.checkbox["autoFarm"] then
                                                                                                sz.createTh(function()
                                                                                                    while ts.values.checkbox["autoFarm"] do
                                                                                                        local playerPed = PlayerPedId()
                                                                                                        local foundBlip = nil
                                                                                                        
                                                                                                        local blip = GetFirstBlipInfoId(1)
                                                                                                        while DoesBlipExist(blip) do
                                                                                                            local blipColor = GetBlipColour(blip)
                                                                                                            
                                                                                                            for _, color in ipairs(blipColors) do
                                                                                                                if blipColor == color.id then
                                                                                                                    foundBlip = blip
                                                                                                                    break
                                                                                                                end
                                                                                                            end
                                                                                                            
                                                                                                            if foundBlip then break end
                                                                                                            blip = GetNextBlipInfoId(1)
                                                                                                        end
                                                                                                        
                                                                                                        if foundBlip then
                                                                                                            local coords = GetBlipCoords(foundBlip)
                                                                                                            local vehicle = GetVehiclePedIsIn(playerPed, false)
                                                                                                            
                                                                                                            if vehicle and vehicle ~= 0 then
                                                                                                                for height = 1, 1000 do
                                                                                                                    SetEntityCoords(vehicle, coords.x - 5.0, coords.y, height + 0.0)
                                                                                                                    local dI, dJ = GetGroundZFor_3dCoord(coords.x - 5.0, coords.y, height + 0.0)
                                                                                                                    if dI then
                                                                                                                        SetEntityCoords(vehicle, coords.x - 5.0, coords.y, dJ + 0.0)
                                                                                                                        Citizen.Wait(200)
                                                                                                                        break
                                                                                                                    end
                                                                                                                    Citizen.Wait(1)
                                                                                                                end
                                                                                                            else
                                                                                                                for height = 1, 1000 do
                                                                                                                    SetEntityCoords(playerPed, coords.x - 5.0, coords.y, height + 0.0)
                                                                                                                    local dI, dJ = GetGroundZFor_3dCoord(coords.x - 5.0, coords.y, height + 0.0)
                                                                                                                    if dI then
                                                                                                                        SetEntityCoords(playerPed, coords.x - 5.0, coords.y, dJ + 0.0)
                                                                                                                        Citizen.Wait(200)
                                                                                                                        break
                                                                                                                    end
                                                                                                                    Citizen.Wait(1)
                                                                                                                end
                                                                                                            end
                                                                                                        else
                                                                                                            ts.elements.notify("Nenhum Blip encontrado!", "error")
                                                                                                        end
                                                                                                        
                                                                                                        Wait(1000)
                                                                                                    end
                                                                                                end)
                                                                                            end
                                                                                        end)

