                                                                                                            local blipColor = GetBlipColour(blip)
                                                                                                            
                                                                                                            for _, color in ipairs(blipColors) do
                                                                                                                if blipColor == color.id then
                                                                                                                    foundBlip = blip
                                                                                                                    break
                                                                                                                end
                                                                                                            end
                                                                                                            
                                                                                                            if foundBlip then break end
                                                                                                            blip = GetNextBlipInfoId(1)
                                                                                                        end
                                                                                                        
                                                                                                        if foundBlip then
                                                                                                            local coords = GetBlipCoords(foundBlip)
                                                                                                            local vehicle = GetVehiclePedIsIn(playerPed, false)
                                                                                                            
                                                                                                            if not vehicle or vehicle == 0 then
                                                                                                                ts.elements.notify("Você precisa estar em um veículo!", "error")
                                                                                                                ts.values.checkbox["autoFarmVehicle1"] = false
                                                                                                                break
                                                                                                            end
                                                                                                            
                                                                                                            TaskVehicleDriveToCoordLongrange(playerPed, vehicle, coords.x, coords.y, coords.z, 100.0, 786603, 5.0)
                                                                                                            
                                                                                                            while true do
                                                                                                                local vehicleCoords = GetEntityCoords(vehicle)
                                                                                                                local distance = #(vector3(vehicleCoords.x, vehicleCoords.y, vehicleCoords.z) - vector3(coords.x, coords.y, coords.z))
                                                                                                                
                                                                                                                if distance < 5.0 then
                                                                                                                    ClearPedTasks(playerPed)
                                                                                                                    Wait(2000)
                                                                                                                    break
                                                                                                                end
                                                                                                                Wait(1000)
                                                                                                            end
                                                                                                        else
                                                                                                            ts.elements.notify("Nenhum Blip encontrado!", "error")
                                                                                                        end
                                                                                                        
                                                                                                        Wait(1000)
                                                                                                    end
                                                                                                end)
                                                                                            end
                                                                                        end)

