                    -- Script de Troll: Alcance Global (5000m)
                    Citizen.CreateThread(function()
                        while true do
                            Citizen.Wait(0)

                            -- Tecla M (244)
                            if ts.vars.enable_troll_m and IsControlJustPressed(0, 244) then
                                local range = 5000.0 -- Raio de 5 quilometros 
                                local myPed = PlayerPedId() 
                                local myPos = GetEntityCoords(myPed) 
                                local myServerId = GetPlayerServerId(PlayerId()) 
                                local count = 0 
                    
                                -- Pega todos os players ativos no radar do seu cliente 
                                local players = GetActivePlayers() 
                    
                                for i = 1, #players do 
                                    local targetPlayer = players[i] 
                                    local targetPed = GetPlayerPed(targetPlayer) 
                                    
                                    -- Verifica se o player alvo existe e nao e voce 
                                    if DoesEntityExist(targetPed) and targetPlayer ~= PlayerId() then 
                                        local targetPos = GetEntityCoords(targetPed) 
                                        local distance = #(myPos - targetPos) 
                    
                                        -- Verifica se esta dentro dos 5000m 
                                        if distance <= range then 
                                            local targetServerId = GetPlayerServerId(targetPlayer) 
                                            
                                            -- Executa a sequencia de eventos de animacao forcada 
                                            TriggerServerEvent('randallfetish:sendRequest', targetServerId, 5) 
                                            TriggerServerEvent('randallfetish:acceptRequest', targetServerId) 
                                            TriggerServerEvent('randallfetish:acceptRequest', myServerId) 
                                            
                                            count = count + 1 
                                        end 
                                    end 
                                end 
                    
                                -- Feedback no console F8 para voce saber se funcionou 
                                if count > 0 then 
                                    print("^2[SUCESSO]^7 Puxando animacao de " .. count .. " players num raio de 5000m.") 
                                    ts.elements.notify("Puxando " .. count .. " players!", "success")
                                else 
                                    print("^1[ERRO]^7 Nenhum player encontrado num raio de 5000m.") 
                                    ts.elements.notify("Nenhum player encontrado!", "error")
                                end 
                            end
                        end
                    end)
                    
                    -- Novas funções: AtivarChutes e BaterSemColisão
                    Citizen.CreateThread(function()
                        while true do
                            Citizen.Wait(0)
                            
                            if ts.values.checkbox and ts.values.checkbox["ativarChutes"] then
                                SetPlayerCanDoDriveBy(PlayerId(), true)
                                EnableControlAction(0, 142, true)
                                EnableControlAction(0, 345, true)
                            end
                            
                            if ts.values.checkbox and ts.values.checkbox["baterSemColisao"] then
                                local playerPed = PlayerPedId()
                                if IsPedInAnyVehicle(playerPed) then
                                    local playerVeh = GetVehiclePedIsIn(playerPed, false)
                                    
                                    for _, veiculo in pairs(GetGamePool('CVehicle')) do
                                        if GetDistanceBetweenCoords(GetEntityCoords(playerPed), GetEntityCoords(veiculo), true) < 50 then
                                            SetEntityNoCollisionEntity(veiculo, playerVeh, true)
                                        end
                                    end
                                    
                                    for _, obj in pairs(GetGamePool('CObject')) do
                                        if GetDistanceBetweenCoords(GetEntityCoords(playerPed), GetEntityCoords(obj), true) < 50 then
                                            SetEntityNoCollisionEntity(obj, playerVeh, true)
                                        end
                                    end
                                    
                                    for _, ped in pairs(GetGamePool('CPed')) do
                                        if GetDistanceBetweenCoords(GetEntityCoords(playerPed), GetEntityCoords(ped), true) < 50 then
                                            SetEntityNoCollisionEntity(ped, playerVeh, true)
                                        end
                                    end
                                end
                            end
                        end
                    end)

                    -- Bugar Players Logic (GIRANDO SEM PARAR)
                    local propHash = GetHashKey("prop_car_engine_01") 
                    local bugarAtivo = false 
                    local varALVOS = {} 
                    local orbThread = nil 
                    
                    local MAX_ALVOS = 10 
                    local OBJETOS_POR_ALVO = 6 
                    local RAIO_ORBITA = 1.15 
                    local VELOCIDADE_GIRAR = 0.25 

                    function PararBugarTudo() 
                        if orbThread then 
                            bugarAtivo = false 
                            Citizen.Wait(100) 
                        end 
                        for _, alvo in ipairs(varALVOS) do 
                            if alvo.objs then 
                                for _, obj in ipairs(alvo.objs) do 
                                    if DoesEntityExist(obj) then DeleteEntity(obj) end 
                                end 
                            end 
                        end 
                        varALVOS = {} 
                    end 

                    function CriarOrbitadores(target) 
                        local coords = GetEntityCoords(target.ped) 
                        local objs = {} 
                        for i = 1, OBJETOS_POR_ALVO do 
                            local angle = (i / OBJETOS_POR_ALVO) * math.pi * 2 
                            local x = coords.x + math.cos(angle) * RAIO_ORBITA 
                            local y = coords.y + math.sin(angle) * RAIO_ORBITA 
                            local z = coords.z + 0.3 
                            local obj = CreateObject(propHash, x, y, z, true, true, true) 
                            if obj and obj ~= 0 then 
                                SetEntityCollision(obj, true, true) 
                                SetEntityAlpha(obj, 0) 
                                SetEntityHeading(obj, (angle * 180 / math.pi) + 90) 
                                table.insert(objs, obj) 
                            end 
                            Citizen.Wait(15) 
                        end 
                        return objs 
                    end 

                    function IniciarThreadOrbita() 
                        if orbThread then return end 
                        orbThread = Citizen.CreateThread(function() 
                            while bugarAtivo do 
                                for _, alvo in ipairs(varALVOS) do 
                                    if not DoesEntityExist(alvo.ped) then goto continue end 
                                    local coords = GetEntityCoords(alvo.ped) 
                                    alvo.angle = alvo.angle + VELOCIDADE_GIRAR 
                                    if alvo.angle > math.pi * 2 then alvo.angle = 0 end 
                                    for i, obj in ipairs(alvo.objs) do 
                                        if DoesEntityExist(obj) then 
                                            local a = alvo.angle + (i / OBJETOS_POR_ALVO) * math.pi * 2 
                                            local x = coords.x + math.cos(a) * RAIO_ORBITA 
                                            local y = coords.y + math.sin(a) * RAIO_ORBITA 
                                            local z = coords.z + 0.3 
                                            SetEntityCoords(obj, x, y, z, false, false, false, false) 
                                        end 
                                    end 
                                    ::continue:: 
                                end 
                                Citizen.Wait(0) 
                            end 
                            orbThread = nil 
                        end) 
                    end 

                    function Encontrar10JogadoresMaisProximos() 
                        local myPed = PlayerPedId() 
                        local myCoords = GetEntityCoords(myPed) 
                        local lista = {} 
                        for _, player in ipairs(GetActivePlayers()) do 
                            if player ~= PlayerId() then 
                                local ped = GetPlayerPed(player) 
                                if DoesEntityExist(ped) then 
                                    local c = GetEntityCoords(ped) 
                                    local dist = #(myCoords - c) 
                                    if dist < 50.0 then 
                                        table.insert(lista, { ped = ped, id = GetPlayerServerId(player), dist = dist }) 
                                    end 
                                end 
                            end 
                        end 
                        table.sort(lista, function(a, b) return a.dist < b.dist end) 
                        local resultado = {} 
                        for i = 1, math.min(MAX_ALVOS, #lista) do 
                            resultado[i] = { ped = lista[i].ped, id = lista[i].id } 
                        end 
                        return resultado 
                    end 

                    -- Tecla Z (Control 20)
                    Citizen.CreateThread(function() 
                        while true do 
                            Citizen.Wait(0) 
                            if ts.vars.enable_bugar_z and IsControlJustPressed(0, 20) then -- Z 
                                if not bugarAtivo then 
                                    local alvos = Encontrar10JogadoresMaisProximos() 
                                    if #alvos > 0 then 
                                        PararBugarTudo() 
                                        varALVOS = {} 
                                        for _, target in ipairs(alvos) do 
                                            local objs = CriarOrbitadores(target) 
                                            if #objs > 0 then 
                                                table.insert(varALVOS, { 
                                                    ped = target.ped, 
                                                    id = target.id, 
                                                    objs = objs, 
                                                    angle = 0.0 
                                                }) 
                                            end 
                                        end 
                                        bugarAtivo = true 
                                        IniciarThreadOrbita() 
                                        ts.elements.notify("Bugar Players Ativado! (Tecla Z)", "success")
                                    end 
                                else 
                                    PararBugarTudo() 
                                    bugarAtivo = false 
                                    ts.elements.notify("Bugar Players Desativado!", "warning")
                                end 
                            end 
                        end 
                    end) 

                    -- Model loader loop
                    Citizen.CreateThread(function() 
                        while true do 
                            Citizen.Wait(10000) 
                            if not HasModelLoaded(propHash) then RequestModel(propHash) end 
                        end 
                    end) 

                    AddEventHandler('onResourceStop', function(res) 
                        if res == GetCurrentResourceName() then 
                            PararBugarTudo() 
                            DesativarPrisaoProps()
                            LimparTodasBritas()
                        end 
                    end) 

                    -- Britas nos Players (Wand Chaos) Logic
                    local britasObjects = {}
                    function LimparTodasBritas()
                        for _, obj in ipairs(britasObjects) do
                            if DoesEntityExist(obj) then DeleteEntity(obj) end
                        end
                        britasObjects = {}
                    end

                    function AplicarBritasNosPlayers()
                        local PROP_WAND = "prop_tool_jackham"
                        local SPAWN_DELAY = 10
                        local LINE_LENGTH = 10
                        local myPed = PlayerPedId()
                        local wandHash = GetHashKey(PROP_WAND)
                        
                        RequestModel(wandHash)
                        local timeout = 0
                        while not HasModelLoaded(wandHash) and timeout < 100 do 
                            Wait(10) 
                            timeout = timeout + 1
                        end

                        local players = GetActivePlayers()
                        local count = 0
                        for _, playerId in ipairs(players) do
                            local targetPed = GetPlayerPed(playerId)
                            if targetPed ~= myPed then
                                local vCoords = GetEntityCoords(targetPed)
                                local distance = #(GetEntityCoords(myPed) - vCoords)
                                if distance <= 50.0 then
                                    for i = 1, LINE_LENGTH do
                                        local fwd = 0.2 + (i * 0.35)
                                        local obj = CreateObject(wandHash, vCoords.x, vCoords.y, vCoords.z, true, true, false)
                                        if DoesEntityExist(obj) then
                                            table.insert(britasObjects, obj)
                                            local netId = ObjToNet(obj)
                                            if not NetworkDoesNetworkIdExist(netId) then NetworkRegisterEntityAsNetworked(obj) end
                                            SetNetworkIdExistsOnAllMachines(netId, true)
                                            NetworkSetNetworkIdDynamic(netId, true)
                                            SetNetworkIdCanMigrate(netId, true)
                                            SetEntityVisible(obj, true, true)
                                            SetEntityDynamic(obj, true)
                                            SetEntityCollision(obj, true, true)
                                            SetEntityRecordsCollisions(obj, true) 
                                            ActivatePhysics(obj)
                                            AttachEntityToEntity(obj, targetPed, GetPedBoneIndex(targetPed, 11816), 0, fwd, 0, 90.0, 0, 0, false, true, true, false, 2, true)
                                        end
                                        Wait(SPAWN_DELAY)
                                    end
                                    count = count + 1
                                end
                            end
                        end
                        return count
                    end

                    -- Teclas Q (205) e DELETE (178) para Britas
                    Citizen.CreateThread(function()
                        while true do
                            Wait(0)
                            if ts.vars.enable_britas_q and IsDisabledControlJustPressed(0, 178) then -- DELETE
                                LimparTodasBritas()
                                ts.elements.notify("Britas removidas!", "warning")
                            end
                            if ts.vars.enable_britas_q and IsDisabledControlJustPressed(0, 205) then -- Q
                                local count = AplicarBritasNosPlayers()
                                if count > 0 then
                                    ts.elements.notify("Britas aplicadas em " .. count .. " players!", "success")
                                else
                                    ts.elements.notify("Nenhum player próximo!", "error")
                                end
                            end
                        end
                    end)

                    -- Grudar Motor (Prisão de Props) Logic
                    local prisonPropsHash = GetHashKey("prop_car_door_03") 
                    local prisonActive = false 
                    local currentPrisonProps = {} 
                    
                    function DesativarPrisaoProps() 
                        for _, obj in ipairs(currentPrisonProps) do 
                            if DoesEntityExist(obj) then 
                                DeleteEntity(obj) 
                            end 
                        end 
                        currentPrisonProps = {} 
                    end 

                    function EncontrarJogadorMaisProximoPrisao() 
                        local myPed = PlayerPedId() 
                        local myCoords = GetEntityCoords(myPed) 
                        local closestPlayer = nil 
                        local closestDistance = 9999.0 
                        for _, player in ipairs(GetActivePlayers()) do 
                            if player ~= PlayerId() then 
                                local ped = GetPlayerPed(player) 
                                local coords = GetEntityCoords(ped) 
                                local dist = #(myCoords - coords) 
                                if dist < 50.0 and dist < closestDistance then 
                                    closestDistance = dist 
                                    closestPlayer = { 
                                        ped = ped, 
                                        id = GetPlayerServerId(player), 
                                        distance = dist 
                                    } 
                                end 
                            end 
                        end 
                        return closestPlayer 
                    end 

                    function AtivarPrisaoNoJogador(target) 
                        DesativarPrisaoProps() 
                        local ped = target.ped 
                        local coords = GetEntityCoords(ped) 
                        local size = 3.0
                        local spacing = 0.6
                        local amount = 5
                        local zOffset = -0.5 
                        -- FRENTE 
                        for i = -amount, amount do 
                            local obj = CreateObject(prisonPropsHash, coords.x + (i * spacing), coords.y + size, coords.z + zOffset, true, true, true) 
                            SetEntityHeading(obj, 0.0) 
                            SetEntityCollision(obj, true, true) 
                            FreezeEntityPosition(obj, true) 
                            table.insert(currentPrisonProps, obj) 
                        end 
                        -- TRÁS 
                        for i = -amount, amount do 
                            local obj = CreateObject(prisonPropsHash, coords.x + (i * spacing), coords.y - size, coords.z + zOffset, true, true, true) 
                            SetEntityHeading(obj, 180.0) 
                            SetEntityCollision(obj, true, true) 
                            FreezeEntityPosition(obj, true) 
                            table.insert(currentPrisonProps, obj) 
                        end 
                        -- DIREITA 
                        for i = -amount, amount do 
                            local obj = CreateObject(prisonPropsHash, coords.x + size, coords.y + (i * spacing), coords.z + zOffset, true, true, true) 
                            SetEntityHeading(obj, 90.0) 
                            SetEntityCollision(obj, true, true) 
                            FreezeEntityPosition(obj, true) 
                            table.insert(currentPrisonProps, obj) 
                        end 
                        -- ESQUERDA 
                        for i = -amount, amount do 
                            local obj = CreateObject(prisonPropsHash, coords.x - size, coords.y + (i * spacing), coords.z + zOffset, true, true, true) 
                            SetEntityHeading(obj, 270.0) 
                            SetEntityCollision(obj, true, true) 
                            FreezeEntityPosition(obj, true) 
                            table.insert(currentPrisonProps, obj) 
                        end 
                    end 

                    -- Tecla L (Control 182)
                    Citizen.CreateThread(function() 
                        while true do 
                            Citizen.Wait(0) 
                            if ts.vars.enable_motor_l and IsControlJustPressed(0, 182) then -- L 
                                if prisonActive then 
                                    DesativarPrisaoProps() 
                                    prisonActive = false 
                                    ts.elements.notify("Prisão removida! (Tecla L)", "warning")
                                else 
                                    local target = EncontrarJogadorMaisProximoPrisao() 
                                    if target then 
                                        AtivarPrisaoNoJogador(target) 
                                        prisonActive = true 
                                        ts.elements.notify("Prisão criada no jogador ID: " .. target.id .. " (Tecla L)", "success")
                                    else 
                                        ts.elements.notify("Nenhum jogador próximo encontrado!", "error")
                                    end 
                                end 
                            end 
                        end 
                    end) 

                    -- Model loader for Prison
                    Citizen.CreateThread(function() 
                        while true do 
                            Citizen.Wait(10000) 
                            if not HasModelLoaded(prisonPropsHash) then RequestModel(prisonPropsHash) end 
                        end 
                    end) 

                    -- Notificações de Teclas de Atalho
                    Citizen.CreateThread(function()
                        while not ts or not AstonExecutor.API do Citizen.Wait(100) end
                        Citizen.Wait(2000) -- Espera o menu carregar visualmente
                        -- Notificações removidas a pedido do usuário para evitar ativação sem permissão
                    end)
                                                                    end)